  ('tecnica.liso_1c', 'es', 'tecnica', 10, '{"hecho":"tipoRizoPrincipal","op":"eq","valor":"1C"}'::jsonb, '{"tecnicaDefinicion":"Secado natural","tecnicaDescripcion":"Lava con shampoo suave y acondicionador. Aplica leave-in en cabello húmedo y peina de puntas a raíz con peine de dientes anchos. Haz scrunch suave en las puntas para potenciar la ondulación sutil. Deja secar sin tocar para evitar frizz. Si usas calor, aplica protector térmico antes.","metodoSecado":"Secado natural o difusor en frío","gelRecomendado":""}'::jsonb, false, 'publicada', NULL),
  ('tecnica.liso_1a_1b', 'es', 'tecnica', 20, '{"hecho":"tipoRizoPrincipal","op":"en","valor":["1A","1B"]}'::jsonb, '{"tecnicaDefinicion":"Secado natural","tecnicaDescripcion":"Lava con shampoo suave y acondicionador hidratante. Aplica leave-in en cabello húmedo y peina con peine de dientes anchos. Deja secar sin tocar para máximo brillo y sin frizz. Evita frotar con la toalla — usa microinfibra o camiseta de algodón.","metodoSecado":"Secado natural o difusor en frío","gelRecomendado":""}'::jsonb, false, 'publicada', NULL),
  ('tecnica.ondulado_2a_2b', 'es', 'tecnica', 30, '{"hecho":"tipoRizoPrincipal","op":"en","valor":["2A","2B"]}'::jsonb, '{"tecnicaDefinicion":"Scrunch","tecnicaDescripcion":"Aplica crema de peinar en el cabello húmedo. Distribuye con rake (peine de dientes anchos) de puntas a raíz. Luego haz scrunch (aprieta el cabello de abajo hacia arriba) para reforzar las ondas. Deja secar sin tocar.","metodoSecado":"Difusor en calor bajo o secado al aire libre","gelRecomendado":"Gel definidor liviano"}'::jsonb, false, 'publicada', NULL),
  ('tecnica.ondulado_2c_3a', 'es', 'tecnica', 40, '{"hecho":"tipoRizoPrincipal","op":"en","valor":["2C","3A"]}'::jsonb, '{"tecnicaDefinicion":"Rake & Shake + Scrunch","tecnicaDescripcion":"Aplica crema de peinar sección por sección. Pasa el peine de dientes anchos (rake) de medios a puntas para separar rizos. Agita las puntas suavemente (shake) para activar el patrón. Finaliza con scrunch para compactar el gel.","metodoSecado":"Difusor en calor medio","gelRecomendado":"Gel definidor o crema de peinar"}'::jsonb, false, 'publicada', NULL),
  ('tecnica.rizado_3b_3c_fino', 'es', 'tecnica', 50, '{"todas":[{"hecho":"tipoRizoPrincipal","op":"en","valor":["3B","3C"]},{"hecho":"grosor","op":"eq","valor":"fino"}]}'::jsonb, '{"tecnicaDefinicion":"Shingling suave","tecnicaDescripcion":"Divide el cabello en secciones pequeñas. Aplica crema de peinar rizo por rizo, deslizando los dedos desde la raíz hasta las puntas. Evita productos muy pesados que aplanen el volumen.","metodoSecado":"Difusor en calor bajo","gelRecomendado":"Crema de peinar + gel definidor"}'::jsonb, false, 'publicada', NULL),
  ('tecnica.rizado_3b_3c', 'es', 'tecnica', 60, '{"hecho":"tipoRizoPrincipal","op":"en","valor":["3B","3C"]}'::jsonb, '{"tecnicaDefinicion":"Praying Hands + Scrunch","tecnicaDescripcion":"Frota la crema de peinar entre las palmas y aplica deslizando ambas manos hacia abajo por cada sección (como si rezaras con el cabello dentro). Luego haz scrunch para compactar el rizo. Aplica gel encima con scrunch final.","metodoSecado":"Difusor en calor bajo-medio","gelRecomendado":"Crema de peinar + gel definidor"}'::jsonb, false, 'publicada', NULL),
  ('tecnica.afro_4a', 'es', 'tecnica', 70, '{"hecho":"tipoRizoPrincipal","op":"eq","valor":"4A"}'::jsonb, '{"tecnicaDefinicion":"Shingling","tecnicaDescripcion":"Divide el cabello en secciones pequeñas. Aplica gel cremoso afro rizo por rizo, deslizando los dedos desde raíz hasta punta para definir cada espiral. Trabaja con el cabello muy húmedo para mejor agarre.","metodoSecado":"Difusor en calor bajo o secado al aire libre","gelRecomendado":"Gel cremoso afro + crema de peinar"}'::jsonb, false, 'publicada', NULL),
  ('tecnica.afro_4b_densidad_alta', 'es', 'tecnica', 80, '{"todas":[{"hecho":"tipoRizoPrincipal","op":"eq","valor":"4B"},{"hecho":"densidad","op":"eq","valor":"alta"}]}'::jsonb, '{"tecnicaDefinicion":"Twist Out","tecnicaDescripcion":"Divide en secciones. Aplica gel cremoso y forma twist (trenzas de 2 hilos) en cada sección. Deja secar completamente antes de soltar. Para día 2-3: twist-out para revivir la definición.","metodoSecado":"Secado al aire libre preferible (el calor puede dañar la estructura)","gelRecomendado":"Gel cremoso afro"}'::jsonb, false, 'publicada', NULL),
  ('tecnica.afro_4b', 'es', 'tecnica', 81, '{"hecho":"tipoRizoPrincipal","op":"eq","valor":"4B"}'::jsonb, '{"tecnicaDefinicion":"Finger Coils o Shingling","tecnicaDescripcion":"Divide en secciones. Aplica gel cremoso y forma twist (trenzas de 2 hilos) en cada sección. Deja secar completamente antes de soltar. Para día 2-3: twist-out para revivir la definición.","metodoSecado":"Secado al aire libre preferible (el calor puede dañar la estructura)","gelRecomendado":"Gel cremoso afro"}'::jsonb, false, 'publicada', NULL),
