  ('config.disclaimer_productos', 'es', 'config', 10, NULL, '{"campo":"disclaimerProductos","texto":"Estas recomendaciones son técnicas y aplican a productos de cualquier marca. Tu estilista puede sugerirte marcas específicas que cumplan con estas características según tu presupuesto y disponibilidad local."}'::jsonb, false, 'publicada', NULL),
  ('nota.proteina', 'es', 'nota', 10, '{"hecho":"tratamientoPrincipal","op":"eq","valor":"Reconstrucción"}'::jsonb, '{"textos":["Prioridad alta en proteína — usa mascarilla reconstructora con queratina hidrolizada."]}'::jsonb, false, 'publicada', NULL),
  ('nota.corte_puntas', 'es', 'nota', 20, '{"todas":[{"alguna":[{"hecho":"danoQuimico","op":"verdadero"},{"hecho":"danoTermico","op":"verdadero"}]},{"hecho":"puntasSeveras","op":"verdadero"}]}'::jsonb, '{"textos":["Se recomienda corte de puntas para eliminar el daño severo."]}'::jsonb, false, 'publicada', NULL),
  ('nota.transicion', 'es', 'nota', 30, '{"hecho":"transicion","op":"verdadero"}'::jsonb, '{"textos":["Tratar zona natural y zona procesada por separado. Recomendar corte progresivo de la zona química."]}'::jsonb, false, 'publicada', NULL),
