  ('nota.sellado_afro', 'es', 'nota', 60, '{"hecho":"tipoRizoPrincipal","op":"en","valor":["4B","4C"]}'::jsonb, '{"textos":["Sella SIEMPRE con aceite después de aplicar el gel para retener humedad."]}'::jsonb, false, 'publicada', NULL),
  ('nota.mascarilla_termica', 'es', 'nota', 70, '{"hecho":"tratReconstructor","op":"verdadero"}'::jsonb, '{"textos":["Mascarilla reconstructora: dejar actuar 20-30 min con calor (gorro térmico) para máxima reconstrucción."]}'::jsonb, false, 'publicada', NULL),
  ('nota.porosidad_baja', 'es', 'nota', 80, '{"hecho":"porosidad","op":"eq","valor":"baja"}'::jsonb, '{"textos":["Porosidad baja: clarifica 1 vez al mes para remover acumulación de producto."]}'::jsonb, false, 'publicada', NULL),
  ('nota.porosidad_alta', 'es', 'nota', 90, '{"hecho":"porosidad","op":"eq","valor":"alta"}'::jsonb, '{"textos":["Porosidad alta: sella SIEMPRE con aceite o manteca después de hidratar para retener la humedad.","Usa leave-in cremoso (no en spray) para mayor nutrición."]}'::jsonb, false, 'publicada', NULL),
  ('nota.caspa', 'es', 'nota', 100, '{"hecho":"tieneCaspa","op":"verdadero"}'::jsonb, '{"textos":["Cuero cabelludo: considerar shampoo medicado 1x por semana.","Si la caspa persiste más de 4 semanas, consultar dermatólogo."]}'::jsonb, false, 'publicada', NULL),
  ('nota.embarazo', 'es', 'nota', 110, '{"hecho":"embarazo","op":"verdadero"}'::jsonb, '{"textos":["Embarazo/lactancia: evitar keratina y productos con formol. Preferir ingredientes naturales."]}'::jsonb, false, 'publicada', NULL),
  ('nota.caida', 'es', 'nota', 120, '{"hecho":"tieneCaida","op":"verdadero"}'::jsonb, '{"textos":["Caída excesiva: puede tener causa interna (estrés, anemia, tiroides, postparto). Recomendar consulta médica si persiste más de 3 meses."]}'::jsonb, false, 'publicada', NULL),
  ('nota.estres', 'es', 'nota', 130, '{"hecho":"nivelEstres","op":"eq","valor":"alto"}'::jsonb, '{"textos":["Nivel de estrés alto: puede contribuir a la caída y fragilidad del cabello."]}'::jsonb, false, 'publicada', NULL),
  ('casa.dia_lavado.base', 'es', 'cuidado_casa', 10, NULL, '{"campo":"diaLavado","textos":["Detangle en secciones con el acondicionador puesto (sin enjuagar)","Aplica mascarilla / tratamiento según cronograma","Enjuaga con agua fría para cerrar la cutícula","Aplica leave-in en cabello húmedo","Aplica crema de peinar + gel con la técnica indicada","Seca con toalla de microfibra o camiseta de algodón (sin frotar)","Usa difusor o deja secar al aire"]}'::jsonb, false, 'publicada', NULL),
  ('casa.nocturno.base', 'es', 'cuidado_casa', 20, NULL, '{"campo":"nocturno","textos":["Usa bonnet de satín o funda de almohada de seda para dormir","Haz una piña suelta (ponytail en la coronilla sin apretar) para conservar los rizos","Si el cabello está muy seco, aplica 1-2 gotas de aceite en las puntas antes del bonnet"]}'::jsonb, false, 'publicada', NULL),
  ('casa.refresh.base', 'es', 'cuidado_casa', 30, NULL, '{"campo":"refresh","textos":["Mezcla agua + leave-in en spray (proporción 50/50)","Aplica en secciones y scruncha suavemente","Si los rizos perdieron forma: aplica un poco de gel fresco y scruncha","Seca con difusor en frío o deja secar al aire"]}'::jsonb, false, 'publicada', NULL),
  ('casa.evitar.base', 'es', 'cuidado_casa', 40, NULL, '{"campo":"evitar","textos":["Cepillar el cabello en seco (rompe los rizos y genera frizz)","Toalla de algodón (usa microfibra o camiseta)","Dormir sin protección (bonnet o funda de satín)","Calor directo sin protector térmico"]}'::jsonb, false, 'publicada', NULL),
  ('casa.evitar.porosidad_baja', 'es', 'cuidado_casa', 50, '{"hecho":"porosidad","op":"eq","valor":"baja"}'::jsonb, '{"campo":"evitar","textos":["Aceites pesados (coco, ricino) — se acumulan en cutícula cerrada"]}'::jsonb, false, 'publicada', NULL),
  ('casa.dia_lavado.porosidad_baja', 'es', 'cuidado_casa', 51, '{"hecho":"porosidad","op":"eq","valor":"baja"}'::jsonb, '{"campo":"diaLavado","textos":["Aplica mascarilla con gorro térmico para abrir la cutícula y permitir absorción"]}'::jsonb, false, 'publicada', NULL),
  ('casa.dia_lavado.porosidad_alta', 'es', 'cuidado_casa', 52, '{"hecho":"porosidad","op":"eq","valor":"alta"}'::jsonb, '{"campo":"diaLavado","textos":["Aplica técnica LOC o LCO: Leave-in → Oil (aceite) → Cream (crema) para retener humedad"]}'::jsonb, false, 'publicada', NULL),
  ('casa.evitar.porosidad_alta', 'es', 'cuidado_casa', 53, '{"hecho":"porosidad","op":"eq","valor":"alta"}'::jsonb, '{"campo":"evitar","textos":["Calor directo (agrava la apertura de cutícula)"]}'::jsonb, false, 'publicada', NULL),
  ('casa.evitar.caida', 'es', 'cuidado_casa', 60, '{"hecho":"tieneCaida","op":"verdadero"}'::jsonb, '{"campo":"evitar","textos":["Peinados tensos (colas apretadas, trenzas pegadas al cuero cabelludo)"]}'::jsonb, false, 'publicada', NULL),
  ('intervalo.urgente', 'es', 'intervalo', 10, '{"alguna":[{"hecho":"puntasSeveras","op":"verdadero"},{"hecho":"tratamientoPrincipal","op":"eq","valor":"Reconstrucción"},{"hecho":"danoQuimico","op":"verdadero"}]}'::jsonb, '{"texto":"Regresar en 2 semanas (seguimiento urgente)"}'::jsonb, false, 'publicada', NULL),
  ('intervalo.tratamiento', 'es', 'intervalo', 20, '{"hecho":"tratamientoPrincipal","op":"neq","valor":"Mantenimiento"}'::jsonb, '{"texto":"Regresar en 3-4 semanas"}'::jsonb, false, 'publicada', NULL),
  ('intervalo.mantenimiento', 'es', 'intervalo', 30, NULL, '{"texto":"Regresar en 6-8 semanas"}'::jsonb, false, 'publicada', NULL),
  ('hecho.f2.calor_frecuente', 'es', 'hecho', 200, '{"hecho":"frecuenciaCalor","op":"en","valor":["2-3-semana","diario"]}'::jsonb, '{"hecho":"calorFrecuente","valor":true}'::jsonb, false, 'borrador', 'Entrega 1 · L-03: tres o más exposiciones semanales a calor.'),
  ('hecho.f2.oleosidad_alta', 'es', 'hecho', 201, '{"alguna":[{"hecho":"ext.grasaRaiz","op":"en","valor":["mismo_dia","1_2_dias"]},{"hecho":"ext.tipoCueroCabelludo","op":"eq","valor":"graso"},{"hecho":"estadoCueroCabelludo","op":"incluye","valor":"Graso (exceso de sebo)"}]}'::jsonb, '{"hecho":"oleosidadAlta","valor":true}'::jsonb, false, 'borrador', 'Entrega 1 · perfil: oleosidad del cuero cabelludo, protagonista en tipo 1 y frecuente en 2A–2B.'),
  ('hecho.f2.alisado_vigente', 'es', 'hecho', 202, '{"alguna":[{"hecho":"quimicos","op":"incluyeAlguno","valor":["Alisado permanente (keratina, formol, japonés)","Relaxer / desrizado químico"]},{"hecho":"ext.procesosQuimicos","op":"incluye","valor":"alisado"}]}'::jsonb, '{"hecho":"alisadoVigente","valor":true}'::jsonb, false, 'borrador', 'Entrega 1 · L-06: alisado químico o keratina en el historial.'),
  ('hecho.f2.tinte_frecuente', 'es', 'hecho', 203, '{"hecho":"ext.frecuenciaTinte","op":"en","valor":["cada_3_6_semanas","cada_8_semanas_o_menos"]}'::jsonb, '{"hecho":"tinteFrecuente","valor":true}'::jsonb, false, 'borrador', 'Entrega 1 · L-09 (coloración cada 8 semanas o menos) y Entrega 2 · C-06 (cobertura cada 3–6 semanas).'),
  ('hecho.f2.tiene_canas', 'es', 'hecho', 204, '{"hecho":"ext.estadoCanas","op":"en","valor":["menos_25","entre_25_50","mas_50"]}'::jsonb, '{"hecho":"tieneCanas","valor":true}'::jsonb, false, 'borrador', 'Entrega 2 · módulo canas: se activa con cualquier porcentaje de canas.'),
  ('hecho.f2.canas_25_mas', 'es', 'hecho', 205, '{"hecho":"ext.estadoCanas","op":"en","valor":["entre_25_50","mas_50"]}'::jsonb, '{"hecho":"canas25Mas","valor":true}'::jsonb, false, 'borrador', 'Entrega 2 · umbral >=25% de canas (C-02, C-06).'),
  ('hecho.f2.protector_instalado', 'es', 'hecho', 206, '{"hecho":"ext.protectorEnUso","op":"en","valor":["trenzas","twists","extensiones"]}'::jsonb, '{"hecho":"protectorInstalado","valor":true}'::jsonb, false, 'borrador', 'Entrega 4 · T4-05/T4-06: peinado protector instalado.'),
  ('hecho.f2.frizz_medio_alto', 'es', 'hecho', 207, '{"alguna":[{"hecho":"ext.nivelFrizz","op":"en","valor":["medio","alto"]},{"hecho":"tieneFrizz","op":"verdadero"}]}'::jsonb, '{"hecho":"frizzMedioAlto","valor":true}'::jsonb, false, 'borrador', 'Entrega 1 · dimensión frizz (protagonista en 1C y tipo 2).'),
  ('hecho.f2.buildup_declarado', 'es', 'hecho', 208, '{"hecho":"ext.acumulacionProducto","op":"eq","valor":"si"}'::jsonb, '{"hecho":"buildUp","valor":true}'::jsonb, false, 'borrador', 'Entrega 1 · O-05: build-up declarado en el flujo de ondulado. Reusa el hecho buildUp del motor (fusión): activa el detox existente sin duplicar reglas.'),
  ('derivacion.f2.areata', 'es', 'derivacion_medica', 20, '{"hecho":"ext.senalesCaida","op":"incluye","valor":"parches_redondos"}'::jsonb, '{"motivo":"Pérdida de cabello en parches redondos u ovalados bien definidos, con piel del parche de aspecto normal y suave.","recomendaciones":["Suspender el diagnóstico cosmético de la zona y derivar a dermatología con prontitud (sospecha orientativa: alopecia areata — el diagnóstico corresponde al dermatólogo).","Registrar la observación en el historial; fotografía comparable solo con autorización expresa de la clienta."]}'::jsonb, true, 'borrador', 'Entrega 2 · guía de cabina: parches redondos → urgencia alta.'),
  ('derivacion.f2.efluvio', 'es', 'derivacion_medica', 21, '{"hecho":"ext.senalesCaida","op":"incluye","valor":"caida_difusa_subita"}'::jsonb, '{"motivo":"Caída difusa, súbita y abundante en los últimos 1–3 meses (frecuente tras parto, cirugía, enfermedad con fiebre, pérdida de peso brusca o estrés intenso).","recomendaciones":["Derivar para evaluación médica (sospecha orientativa: efluvio telógeno — suele ser autolimitado, pero la confirmación es médica).","El salón acompaña solo con cuidado suave: sin tratamientos \"anticaída\" por cuenta propia."]}'::jsonb, true, 'borrador', 'Entrega 2 · guía de cabina: efluvio → urgencia media.'),
  ('derivacion.f2.patron', 'es', 'derivacion_medica', 22, '{"hecho":"ext.senalesCaida","op":"incluye","valor":"raya_ensancha"}'::jsonb, '{"motivo":"Raya que se ensancha de forma progresiva, retroceso de la línea frontal o hebras cada vez más finas en la coronilla.","recomendaciones":["Derivar a dermatología (sospecha orientativa: alopecia de patrón): los manejos médicos responden mejor cuanto antes se inician.","Velli no genera plan cosmético \"anticaída\" para esta condición."]}'::jsonb, true, 'borrador', 'Entrega 2 · guía de cabina: alopecia de patrón → urgencia media-alta.'),
  ('derivacion.f2.traccion_fibrosis', 'es', 'derivacion_medica', 23, '{"hecho":"ext.senalesCaida","op":"incluye","valor":"zonas_lisas_brillantes"}'::jsonb, '{"motivo":"Zonas lisas y brillantes sin vello en sienes o línea frontal: señal de fibrosis por tracción, daño que puede volverse permanente.","recomendaciones":["Soltar toda tensión de inmediato y derivar a dermatología.","Registrar zona y fecha en el historial para el seguimiento."]}'::jsonb, true, 'borrador', 'Entrega 2 · A-02: la derivación aplica cuando hay zonas lisas y brillantes (fibrosis). La tracción SIN fibrosis no deriva: la atiende el salón (ver nota.f2.a02).'),
  ('derivacion.f2.cicatricial', 'es', 'derivacion_medica', 24, '{"hecho":"ext.senalesCaida","op":"incluye","valor":"cuero_inflamado_pustulas"}'::jsonb, '{"motivo":"Pérdida de cabello acompañada de inflamación, pústulas, dolor, descamación severa o piel lisa y brillante sin poros visibles.","recomendaciones":["DERIVACIÓN PRIORITARIA E INMEDIATA (posible alopecia cicatricial u otra condición inflamatoria): el daño folicular puede volverse permanente.","No aplicar tratamientos, masajes ni químicos en la zona."]}'::jsonb, true, 'borrador', 'Entrega 2 · guía de cabina: única señal marcada URGENTE.'),
  ('derivacion.f2.descamacion_placas', 'es', 'derivacion_medica', 25, '{"hecho":"ext.descamacion","op":"eq","valor":"placas_enrojecimiento"}'::jsonb, '{"motivo":"Descamación con placas gruesas y adheridas, enrojecimiento, exudado, dolor o picor intenso en el cuero cabelludo.","recomendaciones":["No aplicar tratamientos, masajes ni químicos en la zona; derivar a dermatología (posible dermatitis seborreica severa, psoriasis o infección).","Registrar fotos en el historial solo si la clienta lo autoriza."]}'::jsonb, true, 'borrador', 'Entrega 1 · L-08 marca el LÍMITE de la resequedad simple; Entrega 2 · guía de cabina.'),
  ('derivacion.f2.protector_lesiones', 'es', 'derivacion_medica', 26, '{"hecho":"ext.senalesProtector","op":"incluye","valor":"pustulas_lesiones"}'::jsonb, '{"motivo":"Cuero cabelludo comprometido bajo el peinado protector: pústulas o lesiones en la piel.","recomendaciones":["Retirar la instalación y derivar a dermatología (protocolo de derivación de la Entrega 2).","No aplicar procesos químicos ni tensión sobre cuero cabelludo con lesiones."]}'::jsonb, true, 'borrador', 'Entrega 4 · T4-06 y banderas de tipos 3–4: piel comprometida bajo protector.'),
  ('derivacion.f2.a06_bloqueos', 'es', 'derivacion_medica', 90, '{"alguna":[{"hecho":"ext.senalesCaida","op":"incluyeAlguno","valor":["parches_redondos","caida_difusa_subita","raya_ensancha","zonas_lisas_brillantes","cuero_inflamado_pustulas"]},{"hecho":"ext.descamacion","op":"eq","valor":"placas_enrojecimiento"},{"hecho":"ext.senalesProtector","op":"incluye","valor":"pustulas_lesiones"}]}'::jsonb, '{"motivo":"Aplican los bloqueos permanentes del motor (regla negativa A-06).","recomendaciones":["BLOQUEO A-06 · No generar plan \"anticaída\" para una condición médica.","BLOQUEO A-06 · No recomendar masajes, estimulantes ni aceites sobre piel enferma, inflamada o lesionada.","BLOQUEO A-06 · No prometer crecimiento ni recuperación de cabello.","BLOQUEO A-06 · No sugerir reemplazar o complementar un tratamiento médico con alternativas \"naturales\".","BLOQUEO A-06 · No aplicar procesos químicos sobre cuero cabelludo con lesiones.","En su lugar: registro en el historial + derivación + plan de acompañamiento (A-01 a A-05) según el caso."]}'::jsonb, true, 'borrador', 'Entrega 2 · A-06 (regla negativa del motor). Validación Keila: "Regla Negativa Inmutable A-06 ... Es nuestro blindaje legal regional". Se implementa como bandera que suma los bloqueos a toda derivación activa; la imposibilidad de generar plan cosmético la fuerza el evaluador en código (no configurable por datos). Si se agrega una señal médica nueva desde el panel, incluirla también en esta condición.'),
  ('tratamiento.f2.rotura_masiva', 'es', 'tratamiento_principal', 1, '{"hecho":"ext.senalesCaida","op":"incluye","valor":"rotura_sin_bulbo"}'::jsonb, '{"texto":"Reconstrucción intensiva (REP-2)"}'::jsonb, false, 'borrador', 'Entrega 2 · A-03: rotura masiva (hebras sin bulbo) es territorio 100% cosmético — REP-2 + suspensión total de la causa + corte sanitario. Transversal a todo tipo.'),
  ('tratamiento.f2.protector', 'es', 'tratamiento_principal', 2, '{"hecho":"protectorInstalado","op":"verdadero"}'::jsonb, '{"texto":"Cuidado bajo peinado protector (PROT-1)"}'::jsonb, false, 'borrador', 'Entrega 4 · T4-05/T4-06: con protector instalado, la ruta del mes es PROT-1 (ciclo repetible mientras dure la instalación).'),
  ('tratamiento.f2.l04_rep2', 'es', 'tratamiento_principal', 3, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"hecho":"elasticidad","op":"eq","valor":"baja"}]}'::jsonb, '{"texto":"Reconstrucción intensiva (REP-2)"}'::jsonb, false, 'borrador', 'Entrega 1 · L-04: elasticidad baja = pérdida estructural de proteína, escalón previo al quiebre. Suspender calor y químicos 4 semanas y reevaluar.'),
  ('tratamiento.f2.o04_rep2', 'es', 'tratamiento_principal', 4, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"elasticidad","op":"eq","valor":"baja"}]}'::jsonb, '{"texto":"Reconstrucción intensiva (REP-2)"}'::jsonb, false, 'borrador', 'Entrega 1 · O-04: déficit proteico en patrón ondulado — sin estructura, ninguna técnica de definición funciona. REP-2 adaptado a onda, styling mínimo.'),
  ('tratamiento.f2.l06_post_alisado', 'es', 'tratamiento_principal', 5, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"hecho":"alisadoVigente","op":"verdadero"}]}'::jsonb, '{"texto":"Mantenimiento post-alisado (MANT-1)"}'::jsonb, false, 'borrador', 'Entrega 1 · L-06: alisado o keratina vigente — preservar el proceso y no sobrecargar. Proteína SOLO si la prueba de elasticidad da baja (en ese caso gana L-04/REP-2, prioridad 3).'),
  ('tratamiento.f2.o06_transicion', 'es', 'tratamiento_principal', 6, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"transicion","op":"verdadero"}]}'::jsonb, '{"texto":"Transición post-química (REP-1)"}'::jsonb, false, 'borrador', 'Entrega 1 · O-06: dos texturas en la misma hebra. REP-1 completo + cortes programados + cero calor. Las notas del motor para transición se conservan y se suman.'),
  ('tratamiento.f2.l03_l09_rep1', 'es', 'tratamiento_principal', 7, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"hecho":"porosidad","op":"eq","valor":"alta"},{"alguna":[{"hecho":"calorFrecuente","op":"verdadero"},{"hecho":"tinteFrecuente","op":"verdadero"}]}]}'::jsonb, '{"texto":"Reparación progresiva (REP-1)"}'::jsonb, false, 'borrador', 'Entrega 1 · L-03 (daño térmico moderado) y L-09 (teñido frecuente con porosidad alta) comparten plan REP-1; el detalle de cada caso vive en sus notas (nota.f2.l03 / nota.f2.l09).'),
  ('tratamiento.f2.o05_detox', 'es', 'tratamiento_principal', 8, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"buildUp","op":"verdadero"}]}'::jsonb, '{"texto":"Detox y reinicio de definición (DEF-1)"}'::jsonb, false, 'borrador', 'Entrega 1 · O-05: ondas apagadas por acumulación — un (1) lavado clarificante + hidratación profunda inmediata, y de ahí en adelante DEF-1. El tratamiento adicional de detox del motor (adicional.detox) también se activa: fusión, no duplicado.'),
  ('tratamiento.f2.l07_l01_l02_eq1', 'es', 'tratamiento_principal', 11, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"alguna":[{"hecho":"oleosidadAlta","op":"verdadero"},{"hecho":"ext.objetivoPrincipal","op":"eq","valor":"volumen"}]}]}'::jsonb, '{"texto":"Equilibrio de raíz ligera (EQ-1)"}'::jsonb, false, 'borrador', 'Entrega 1 · L-01 (raíz grasa, hebra sana), L-02 (raíz grasa + puntas resecas: EQ-1 + sellado de puntas) y L-07 (busca volumen) comparten plan EQ-1; el matiz de cada perfil vive en sus notas y productos.'),
  ('tratamiento.f2.l05_nut1', 'es', 'tratamiento_principal', 12, '{"todas":[{"hecho":"tipoRizoPrincipal","op":"eq","valor":"1C"},{"hecho":"frizzMedioAlto","op":"verdadero"}]}'::jsonb, '{"texto":"Nutrición antifrizz (NUT-1)"}'::jsonb, false, 'borrador', 'Entrega 1 · L-05: 1C con frizz y estática — sellar cutícula y aportar emoliencia sin engrasar.'),
  ('tratamiento.f2.l08_l10_mant1', 'es', 'tratamiento_principal', 13, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"hecho":"hayDano","op":"falso"}]}'::jsonb, '{"texto":"Mantenimiento (MANT-1)"}'::jsonb, false, 'borrador', 'Entrega 1 · L-08 (cuero seco / descamación leve: MANT-1 + cuidado de cuero cabelludo) y L-10 (liso sano: rutina mínima viable — cuando el cabello está bien, Velli lo dice). El liso CON daño sigue a las reglas del motor (reparación).'),
  ('tratamiento.f2.o03_def2', 'es', 'tratamiento_principal', 14, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"porosidad","op":"eq","valor":"alta"},{"alguna":[{"hecho":"tipoRizoPrincipal","op":"eq","valor":"2C"},{"hecho":"ext.objetivoPrincipal","op":"eq","valor":"mas_rizo"}]}]}'::jsonb, '{"texto":"Hidratación profunda + definición intensa (DEF-2)"}'::jsonb, false, 'borrador', 'Entrega 1 · O-03 (2C poroso con frizz alto en clima húmedo — caso Villavicencio) y O-10 con porosidad alta. Primero saciar la hebra, luego sellarla.'),
  ('tratamiento.f2.o07_eq1', 'es', 'tratamiento_principal', 15, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"oleosidadAlta","op":"verdadero"}]}'::jsonb, '{"texto":"Equilibrio de raíz ligera (EQ-1)"}'::jsonb, false, 'borrador', 'Entrega 1 · O-07: onda con raíz grasa — EQ-1 adaptado a onda: limpieza frecuente y suave de la raíz, definición solo de medios a puntas.'),
  ('tratamiento.f2.o08_nut1', 'es', 'tratamiento_principal', 16, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"grosor","op":"eq","valor":"grueso"},{"hecho":"porosidad","op":"neq","valor":"baja"}]}'::jsonb, '{"texto":"Nutrición antifrizz (NUT-1)"}'::jsonb, false, 'borrador', 'Entrega 1 · O-08: onda gruesa y seca sin daño químico — NUT-1 adaptado a onda con sellado en cada lavado.'),
  ('tratamiento.f2.o09_mant1', 'es', 'tratamiento_principal', 17, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"ext.objetivoPrincipal","op":"eq","valor":"mantenimiento"},{"hecho":"hayDano","op":"falso"}]}'::jsonb, '{"texto":"Mantenimiento (MANT-1)"}'::jsonb, false, 'borrador', 'Entrega 1 · O-09: onda sana en equilibrio — sostener, no intervenir. MANT-1 + refresco entre lavados.'),
  ('tratamiento.f2.o01_o02_def1', 'es', 'tratamiento_principal', 18, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"hayDano","op":"falso"}]}'::jsonb, '{"texto":"Definición de onda (DEF-1)"}'::jsonb, false, 'borrador', 'Entrega 1 · O-01 (2A que se aplasta: styling ultraligero), O-02 (2B definición clásica) y O-10 sin porosidad alta. El matiz por subtipo vive en las notas. El ondulado CON daño sigue a las reglas del motor.'),
  ('cronograma.f2.rep2', 'es', 'cronograma', 1, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"REP-2"}'::jsonb, '{"semana1":"Sesión 1: Reconstrucción (proteína) · Sesión 2: Hidratación","semana2":"Sesión 1: Hidratación · Sesión 2: Nutrición","semana3":"Sesión 1: Reconstrucción (proteína) · Sesión 2: Hidratación","semana4":"Sesión 1: Hidratación · Sesión 2: Prueba de elasticidad — decide si se repite el ciclo, se pasa a REP-1 o se propone corte"}'::jsonb, false, 'borrador', 'Entrega 1 · REP-2 (Reconstrucción intensiva): elasticidad baja con riesgo de quiebre (L-04, O-04; también A-03 rotura).'),
  ('cronograma.f2.rep1', 'es', 'cronograma', 2, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"REP-1"}'::jsonb, '{"semana1":"Sesión 1: Hidratación · Sesión 2: Hidratación","semana2":"Sesión 1: Hidratación · Sesión 2: Reconstrucción suave (proteína)","semana3":"Sesión 1: Nutrición · Sesión 2: Hidratación","semana4":"Sesión 1: Reconstrucción suave (proteína) · Sesión 2: Hidratación + prueba de elasticidad de control"}'::jsonb, false, 'borrador', 'Entrega 1 · REP-1 (Reparación progresiva): daño térmico o químico moderado con elasticidad media (L-03, L-09, O-06).'),
  ('cronograma.f2.prot1', 'es', 'cronograma', 3, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"PROT-1"}'::jsonb, '{"semana1":"Sesión 1: Limpieza del cuero cabelludo con champú diluido (aplicador) + secado COMPLETO · Sesión 2: Hidratación ligera de raíces visibles (spray acuoso + aceite ligero)","semana2":"Sesión 1: Hidratación ligera de raíces y largos accesibles · Sesión 2: Revisión de tensión: ¿hay dolor, bultitos o tirantez en bordes? → aflojar o retirar","semana3":"Sesión 1: Limpieza del cuero cabelludo + secado completo · Sesión 2: Hidratación ligera","semana4":"Sesión 1: Hidratación ligera · Sesión 2: Evaluación de la instalación: semanas acumuladas, estado de bordes, decisión de retiro o continuidad (máximo orientativo 4–8 semanas)"}'::jsonb, false, 'borrador', 'Entrega 4 · PROT-1 (Cuidado bajo peinado protector): ciclo de 4 semanas repetible mientras dure la instalación (T4-05, T4-06).'),
  ('cronograma.f2.can2', 'es', 'cronograma', 4, '{"todas":[{"hecho":"tieneCanas","op":"verdadero"},{"hecho":"ext.situacionColor","op":"eq","valor":"en_transicion"}]}'::jsonb, '{"semana1":"Sesión 1: Hidratación + matización de la zona natural · Sesión 2: Refresco o lavado normal","semana2":"Sesión 1: Reparación suave (proteína ligera) en los largos teñidos · Sesión 2: Hidratación","semana3":"Sesión 1: Hidratación + nutrición en puntas · Sesión 2: Lavado normal","semana4":"Sesión 1: Foto de progreso para el Pasaporte Capilar · Sesión 2: Revisión de estrategia visual con la clienta"}'::jsonb, false, 'borrador', 'Entrega 2 · CAN-2 (Transición acompañada, C-05): ciclo repetible mes a mes durante la transición. Módulo transversal: compone sobre cualquier tipo base; el daño estructural (REP) y el protector (PROT-1) tienen prioridad.'),
  ('cronograma.f2.can1', 'es', 'cronograma', 5, '{"todas":[{"hecho":"canas25Mas","op":"verdadero"},{"hecho":"ext.amarillamientoCanas","op":"verdadero"},{"hecho":"ext.situacionColor","op":"neq","valor":"tenida_cobertura"}]}'::jsonb, '{"semana1":"Sesión 1: Hidratación + matización corta (pausa breve, 3–5 min) · Sesión 2: Lavado normal de rutina","semana2":"Sesión 1: Hidratación profunda (semana de descanso del violeta) · Sesión 2: Lavado normal","semana3":"Sesión 1: Hidratación + matización corta · Sesión 2: Lavado normal","semana4":"Sesión 1: Hidratación + evaluación de tono y de resequedad · Sesión 2: Ajuste del protocolo según resultado"}'::jsonb, false, 'borrador', 'Entrega 2 · CAN-1 (Matización y brillo, C-02): amarillamiento de canas >=25% sin tinte de cobertura. Módulo transversal sobre el tipo base.'),
  ('cronograma.f2.eq1', 'es', 'cronograma', 6, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"EQ-1"}'::jsonb, '{"semana1":"Sesión 1: Limpieza equilibrante + hidratación ligera solo en medios y puntas · Sesión 2: Limpieza equilibrante (lavado normal de rutina)","semana2":"Sesión 1: Limpieza + exfoliación suave del cuero cabelludo · Sesión 2: Hidratación ligera de medios a puntas","semana3":"Sesión 1: Limpieza equilibrante · Sesión 2: Hidratación + nutrición solo en puntas","semana4":"Sesión 1: Limpieza + hidratación ligera · Sesión 2: Evaluación: ¿bajó la sensación de grasa? Ajustar frecuencia de lavado"}'::jsonb, false, 'borrador', 'Entrega 1 · EQ-1 (Equilibrio de raíz ligera): cuero cabelludo oleoso con hebra sana o porosidad mixta (L-01, L-02, L-07, O-07).'),
  ('cronograma.f2.nut1', 'es', 'cronograma', 7, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"NUT-1"}'::jsonb, '{"semana1":"Sesión 1: Hidratación · Sesión 2: Nutrición","semana2":"Sesión 1: Nutrición · Sesión 2: Hidratación","semana3":"Sesión 1: Hidratación · Sesión 2: Nutrición","semana4":"Sesión 1: Nutrición + sellado con aceite ligero · Sesión 2: Hidratación + evaluación del frizz"}'::jsonb, false, 'borrador', 'Entrega 1 · NUT-1 (Nutrición antifrizz): hebra gruesa o seca con frizz por cutícula abierta (L-05, O-08; también C-03 cana rebelde).'),
  ('cronograma.f2.def2', 'es', 'cronograma', 8, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"DEF-2"}'::jsonb, '{"semana1":"Sesión 1: Hidratación profunda (mascarilla con tiempo de pausa) + styling con gel de fijación media-alta · Sesión 2: Refresco","semana2":"Sesión 1: Hidratación + styling · Sesión 2: Hidratación ligera o co-wash + refresco","semana3":"Sesión 1: Hidratación profunda + nutrición en puntas + styling · Sesión 2: Refresco","semana4":"Sesión 1: Hidratación + styling · Sesión 2: Evaluación del frizz en día húmedo real"}'::jsonb, false, 'borrador', 'Entrega 1 · DEF-2 (Hidratación profunda + definición intensa): 2C porosos con frizz alto en clima húmedo (O-03, O-10 con porosidad alta).'),
  ('cronograma.f2.def1', 'es', 'cronograma', 9, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"DEF-1"}'::jsonb, '{"semana1":"Sesión 1: Hidratación + styling completo (técnica crema + gel) · Sesión 2: Refresco a mitad de semana (agua + leave-in + scrunch)","semana2":"Sesión 1: Hidratación + styling, ajustando cantidades según resultado de la semana 1 · Sesión 2: Refresco","semana3":"Sesión 1: Hidratación + nutrición en puntas + styling · Sesión 2: Refresco","semana4":"Sesión 1: Hidratación + styling · Sesión 2: Evaluación: fotos comparativas del patrón para el historial"}'::jsonb, false, 'borrador', 'Entrega 1 · DEF-1 (Definición de onda): rutina base de definición para tipo 2 sin daño relevante (O-01, O-02, O-09, O-10).'),
  ('cronograma.f2.mant1', 'es', 'cronograma', 11, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"MANT-1"}'::jsonb, '{"semana1":"Hidratación (una sesión de cuidado por semana basta)","semana2":"Nutrición ligera","semana3":"Hidratación","semana4":"Hidratación o nutrición según sensación de la hebra"}'::jsonb, false, 'borrador', 'Entrega 1 · MANT-1 (Mantenimiento): cabello en equilibrio, de cualquier tipo (L-06, L-08, L-10, O-09). El objetivo es sostener el equilibrio, no intervenirlo.'),
  ('adicional.f2.can1', 'es', 'tratamiento_adicional', 40, '{"todas":[{"hecho":"canas25Mas","op":"verdadero"},{"hecho":"ext.amarillamientoCanas","op":"verdadero"}]}'::jsonb, '{"texto":"Módulo canas: matización y brillo (CAN-1)"}'::jsonb, false, 'borrador', 'Entrega 2 · C-02: el módulo de canas se SUMA al diagnóstico base sin reemplazarlo (arquitectura transversal validada por Keila).'),
  ('adicional.f2.can2', 'es', 'tratamiento_adicional', 41, '{"todas":[{"hecho":"tieneCanas","op":"verdadero"},{"hecho":"ext.situacionColor","op":"eq","valor":"en_transicion"}]}'::jsonb, '{"texto":"Módulo canas: transición acompañada (CAN-2)"}'::jsonb, false, 'borrador', 'Entrega 2 · C-05: transición a canas desde el tinte (proyecto de 12–24 meses).'),
  ('adicional.f2.a01', 'es', 'tratamiento_adicional', 42, '{"hecho":"ext.situacionCaida","op":"en","valor":["en_evaluacion_medica","diagnostico_confirmado_manejo"]}'::jsonb, '{"texto":"Acompañamiento bajo manejo médico (A-01): cuidado de mínima agresión"}'::jsonb, false, 'borrador', 'Entrega 2 · A-01: clienta ya derivada y/o en tratamiento dermatológico. El protagonista es el médico; el salón cuida sin interferir.'),
  ('intervalo.f2.protector', 'es', 'intervalo', 5, '{"hecho":"protectorInstalado","op":"verdadero"}'::jsonb, '{"texto":"Revisión de tensión en 1–2 semanas; retiro de la instalación como cita agendada (máximo orientativo 4–8 semanas)"}'::jsonb, false, 'borrador', 'Entrega 4 · T4-05: el sistema agenda el retiro como cita al momento de instalar.'),
  ('intervalo.f2.can2', 'es', 'intervalo', 6, '{"todas":[{"hecho":"tieneCanas","op":"verdadero"},{"hecho":"ext.situacionColor","op":"eq","valor":"en_transicion"}]}'::jsonb, '{"texto":"Visita mensual con foto de progreso para el Pasaporte Capilar"}'::jsonb, false, 'borrador', 'Entrega 2 · CAN-2: la foto mensual es parte del plan — sostiene la motivación en los meses difíciles de la línea de demarcación.'),
  ('nota.f2.l01', 'es', 'nota', 200, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"hecho":"oleosidadAlta","op":"verdadero"},{"hecho":"porosidad","op":"neq","valor":"alta"}]}'::jsonb, '{"textos":["Raíz grasa con hebra sana: en el cabello liso el sebo viaja sin obstáculos por la hebra recta — aplana el peinado y da sensación de sucio rápido aunque la fibra esté en buen estado. Objetivo del mes: regular la sensación de grasa sin resecar largos.","Técnica clave: lavar con yemas de los dedos (nunca uñas), enjuague final con agua tibia-fría, acondicionador jamás en la raíz, secado con aire frío para cerrar cutícula."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA L-01 (raíz grasa, hebra sana). Pregunta abierta para Keila: ¿lavado diario suave o interdiario para este perfil?'),
  ('nota.f2.l02', 'es', 'nota', 201, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"hecho":"oleosidadAlta","op":"verdadero"},{"alguna":[{"hecho":"estadoPuntas","op":"regex","valor":"abiertas"},{"hecho":"porosidad","op":"eq","valor":"alta"}]}]}'::jsonb, '{"textos":["Desequilibrio raíz-puntas (porosidad mixta), el cuadro más común del liso largo: la raíz se engrasa en horas mientras las puntas, lejos del sebo y castigadas por calor o fricción, se resecan y abren. Tratar como dos cabellos distintos: raíz que se limpia, puntas que se protegen (EQ-1 + sellado de puntas en cada lavado).","Técnica clave: sérum únicamente del medio hacia abajo, sobre cabello húmedo; recoger el cabello sin tensión en la raíz; despuntar cada 8–12 semanas."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA L-02 (raíz grasa, puntas resecas — porosidad mixta).'),
  ('nota.f2.l03', 'es', 'nota', 202, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"hecho":"calorFrecuente","op":"verdadero"},{"hecho":"porosidad","op":"eq","valor":"alta"}]}'::jsonb, '{"textos":["Daño térmico moderado: cutícula erosionada por calor repetido — pérdida de brillo, puntas abiertas, frizz de hebras rotas. La estructura interna aún responde, por lo que es recuperable. Compromiso del mes: protector térmico obligatorio y plancha máximo 1 vez por semana.","Técnica clave: plancha solo sobre cabello 100 % seco y con protector aplicado; temperatura máxima orientativa de 180 °C en hebra fina; una sola pasada lenta en lugar de varias rápidas."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA L-03 (daño térmico moderado).'),
  ('nota.f2.l04', 'es', 'nota', 203, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"hecho":"elasticidad","op":"eq","valor":"baja"}]}'::jsonb, '{"textos":["Elasticidad baja — riesgo de quiebre: pérdida estructural de proteína, la fibra perdió su capacidad de estirar y volver. Es el escalón previo al quiebre masivo y exige frenar toda agresión: suspender calor y procesos químicos durante las 4 semanas y reevaluar elasticidad al cierre.","Técnica clave: desenredar solo en húmedo, con acondicionador y peine de dientes anchos, de puntas a raíz; secar sin fricción con toalla de microfibra; nada de coletas tensas.","Si tras 4 semanas la elasticidad no mejora, la fibra dañada es irreversible: proponer corte progresivo de lo comprometido."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA L-04 (elasticidad baja). Nota para Keila pendiente: cómo comunicar el corte progresivo a la clienta.'),
  ('nota.f2.l05', 'es', 'nota', 204, '{"todas":[{"hecho":"tipoRizoPrincipal","op":"eq","valor":"1C"},{"hecho":"frizzMedioAlto","op":"verdadero"}]}'::jsonb, '{"textos":["1C con frizz y estática: hebra gruesa con leve memoria de onda cuya cutícula se abre con la humedad ambiental; falta sellado y peso ligero que ordene la fibra. Objetivo: sellar cutícula y aportar emoliencia sin engrasar.","Técnica clave: secar con aire medio dirigido de raíz a puntas (a favor de la cutícula) y golpe de aire frío final; evitar cepillar en seco; funda de satén opcional para dormir."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA L-05 (1C con frizz y estática).'),
  ('nota.f2.l06', 'es', 'nota', 205, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"hecho":"alisadoVigente","op":"verdadero"}]}'::jsonb, '{"textos":["Alisado permanente o keratina vigente: la prioridad es preservar el proceso y no sobrecargar. El proceso ya aportó carga proteica — el exceso de proteína adicional puede rigidizar y quebrar. Hidratación semanal; proteína SOLO si la prueba de elasticidad da baja, y en dosis suave.","Técnica clave: espaciar lavados según protocolo del fabricante; no recoger ni marcar el cabello los primeros días post-proceso si el protocolo lo indica.","Bandera amarilla: NO aplicar nuevos procesos químicos (tinte con amoniaco, decoloración) sin evaluar la hebra."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA L-06. Pregunta de fondo para Keila: postura oficial de Velli/KEYSHOP frente a keratinas y alisados.'),
  ('nota.f2.l07', 'es', 'nota', 206, '{"todas":[{"hecho":"tipoRizoPrincipal","op":"eq","valor":"1A"},{"hecho":"grosor","op":"eq","valor":"fino"},{"hecho":"ext.objetivoPrincipal","op":"eq","valor":"volumen"}]}'::jsonb, '{"textos":["Busca volumen (hebra fina): hebra fina y sana que se aplana por su propio peso y por productos que la recargan. No le falta salud: le sobra peso en la rutina. La regla mental: todo lo cremoso, lejos de la raíz; todo lo ligero, hacia la raíz.","Técnica clave: secado cabeza abajo o con cepillo redondo levantando la raíz; aplicar el producto de raíz con el cabello húmedo, antes del secado."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA L-07. Si la clienta reporta pérdida progresiva de densidad, deja de ser regla cosmética: banderas rojas (senalesCaida).'),
  ('nota.f2.l08', 'es', 'nota', 207, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"alguna":[{"hecho":"ext.descamacion","op":"eq","valor":"fina_blanca"},{"hecho":"ext.tipoCueroCabelludo","op":"eq","valor":"seco"}]}]}'::jsonb, '{"textos":["Cuero cabelludo seco o con descamación leve: resequedad simple (no confundir con caspa grasa ni con dermatitis). Suele asociarse a agua muy caliente, lavado excesivo o clima seco. Plan: espaciar lavados, bajar la temperatura del agua, hidratar la piel.","Técnica clave: masaje suave con yemas al aplicar el tónico; agua tibia, nunca caliente.","LÍMITE de esta regla: si hay placas, enrojecimiento, exudado, dolor o picor intenso, no es resequedad simple — derivación obligatoria."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA L-08 (cuero cabelludo seco o descamación leve).'),
  ('nota.f2.l09', 'es', 'nota', 208, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"hecho":"tinteFrecuente","op":"verdadero"},{"hecho":"porosidad","op":"eq","valor":"alta"}]}'::jsonb, '{"textos":["Teñido frecuente con porosidad alta: daño químico acumulativo por colorante — cutícula abierta, color que se lava rápido, sequedad creciente. Recuperable con rutina de reparación y hábitos de protección del color (conecta a futuro con el módulo de colorimetría de Fase 3).","Técnica clave: retocar solo raíz cuando sea posible, en lugar de re-teñir todo el largo; espaciar aplicaciones al máximo que el objetivo de color permita."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA L-09 (teñido frecuente con porosidad alta).'),
  ('nota.f2.l10', 'es', 'nota', 209, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"hecho":"hayDano","op":"falso"},{"hecho":"oleosidadAlta","op":"falso"},{"hecho":"ext.descamacion","op":"neq","valor":"fina_blanca"},{"hecho":"ext.tipoCueroCabelludo","op":"neq","valor":"seco"}]}'::jsonb, '{"textos":["Liso sano — cabello en equilibrio. El riesgo aquí es el contrario al habitual: sobre-tratarlo y romper el balance con exceso de productos o tratamientos innecesarios. Rutina mínima viable + educación de hábitos.","Hábitos: no dormir con el cabello mojado, fricción mínima, despunte de mantenimiento cada 10–12 semanas."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA L-10. Esta regla protege la credibilidad del diagnóstico: cuando el cabello está bien, Velli lo dice. Vender de más erosiona la confianza.'),
  ('nota.f2.o01', 'es', 'nota', 220, '{"todas":[{"hecho":"tipoRizoPrincipal","op":"eq","valor":"2A"},{"hecho":"grosor","op":"eq","valor":"fino"}]}'::jsonb, '{"textos":["2A que se aplasta: patrón de onda débil y sensible al peso — cualquier crema densa o aceite en raíz lo estira. El problema no es falta de tratamiento sino exceso de carga: styling ultraligero. Prohibido por defecto: cremas densas, mantecas y aceites en raíz.","Técnica clave: aplicar el styling con el cabello muy húmedo, scrunch (apretar hacia arriba), secar al aire o con difusor a temperatura baja; no tocar mientras seca."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA O-01 (2A que se aplasta).'),
  ('nota.f2.o02', 'es', 'nota', 221, '{"todas":[{"hecho":"tipoRizoPrincipal","op":"eq","valor":"2B"},{"hecho":"hayDano","op":"falso"}]}'::jsonb, '{"textos":["2B — definición clásica: el perfil ondulado de manual, ondas en S desde los medios que solo necesitan método y constancia para verse definidas. Es el perfil ideal para enseñar la rutina completa de definición y fidelizar.","Técnica clave — secuencia completa: desenredar con acondicionador → aplicar crema y gel por secciones con scrunch → plopping 10–15 minutos con microfibra → difusor → romper el cast (la película rígida del gel) con manos secas al final."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA O-02 (2B — definición clásica).'),
  ('nota.f2.o03', 'es', 'nota', 222, '{"todas":[{"hecho":"tipoRizoPrincipal","op":"eq","valor":"2C"},{"hecho":"porosidad","op":"eq","valor":"alta"}]}'::jsonb, '{"textos":["2C con frizz alto en clima húmedo: hebra ávida de agua — al estar deshidratada y porosa, absorbe la humedad del ambiente y se encrespa. El frizz aquí es síntoma de sed, no de suciedad. Primero saciar la hebra, luego sellarla. La hidratación profunda es semanal e innegociable este mes.","Técnica clave: sellar con gel suficiente para formar cast y romperlo al secar por completo; refresco entre lavados con agua + leave-in; en humedad extrema, capa final de antihumectante (reservado para ocasiones, no como base diaria)."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA O-03 (2C con frizz alto en clima húmedo — caso Villavicencio). Frontera 2C↔3A: criterio de enrutamiento validado por Keila — patrón en mojado sin producto (S sin resorte → tipo 2; resorte → motor de rizos) y objetivo como desempate.'),
  ('nota.f2.o04', 'es', 'nota', 223, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"elasticidad","op":"eq","valor":"baja"}]}'::jsonb, '{"textos":["Onda con elasticidad baja: déficit proteico en patrón ondulado — la fibra perdió memoria. Sin estructura, ninguna técnica de definición funcionará. REP-2 adaptado a onda: reconstructor quincenal alternado con hidratación; styling mínimo durante el mes.","Técnica clave: reevaluar con la prueba de elasticidad al cierre de la semana 4 antes de retomar la rutina de definición."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA O-04 (onda con elasticidad baja).'),
  ('nota.f2.o05', 'es', 'nota', 224, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"buildUp","op":"verdadero"}]}'::jsonb, '{"textos":["Ondas apagadas por acumulación (build-up): la acumulación de producto impermeabiliza la hebra — la hidratación no entra y el patrón se apaga. Antes de tratar hay que limpiar el lienzo: un (1) lavado clarificante, hidratación profunda inmediata, y de ahí en adelante definición con productos aptos (sin siliconas insolubles).","Técnica clave: el clarificante reseca — la mascarilla de hidratación profunda posterior no es opcional, es parte del procedimiento. Clarificante máximo 1 vez al mes."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA O-05 (ondas apagadas por build-up).'),
  ('nota.f2.o06', 'es', 'nota', 225, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"transicion","op":"verdadero"}]}'::jsonb, '{"textos":["Transición post-química: la zona tratada químicamente no recuperará su patrón; la nueva crece sana desde la raíz. El plan gestiona la convivencia de ambas y las expectativas de tiempo: REP-1 completo + cortes programados de las puntas tratadas + cero calor.","Técnica clave: peinados de baja tensión que unifiquen visualmente (ondas con técnica, trenzas suaves); calendario de cortes acordado con la clienta."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA O-06 (transición post-química). Este perfil es la puerta de entrada clásica al mundo KEYSHOP. Las notas de transición del motor se conservan y se suman (fusión).'),
  ('nota.f2.o07', 'es', 'nota', 226, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"oleosidadAlta","op":"verdadero"}]}'::jsonb, '{"textos":["Onda con raíz grasa — el clásico conflicto del ondulado: raíz que pide lavado frecuente y largos que piden respeto. Se resuelve tratando cada zona por separado: limpieza frecuente y suave de la raíz, definición solo de medios a puntas.","Técnica clave: lavar la raíz con yemas y dejar que la espuma limpie los largos solo al enjuagar; nada de acondicionador ni styling en la raíz."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA O-07 (onda con raíz grasa).'),
  ('nota.f2.o08', 'es', 'nota', 227, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"grosor","op":"eq","valor":"grueso"},{"hecho":"porosidad","op":"neq","valor":"baja"}]}'::jsonb, '{"textos":["Onda gruesa y seca: hebra gruesa que necesita más emoliencia de la que recibe — la sequedad opaca el patrón y dispara el frizz. NUT-1 adaptado a onda: nutrición e hidratación alternadas con sellado en cada lavado.","Técnica clave: aplicar por secciones con el cabello empapado; \"squish to condish\" en la ducha (escurrir el acondicionador hacia arriba con agua) para cargar hidratación."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA O-08 (onda gruesa y seca).'),
  ('nota.f2.o09', 'es', 'nota', 228, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"ext.objetivoPrincipal","op":"eq","valor":"mantenimiento"},{"hecho":"hayDano","op":"falso"}]}'::jsonb, '{"textos":["Onda sana — cabello ondulado en equilibrio: el objetivo es sostener, no intervenir. MANT-1 + refresco entre lavados con rutina mínima de su tipo.","Técnica clave — refresco: humedecer, aplicar leave-in ligero y scrunch; dormir con piña alta suelta o funda de satén para conservar el patrón."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA O-09 (onda sana — mantenimiento).'),
  ('nota.f2.o10', 'es', 'nota', 229, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"ext.objetivoPrincipal","op":"eq","valor":"mas_rizo"}]}'::jsonb, '{"textos":["Quiere \"más rizo\": el patrón genético se potencia, no se transforma — una 2B puede lograr su mejor versión de onda marcada, pero no convertirse en 3A. La regla gestiona técnica y expectativa a la vez. Tu onda no se convierte en otro patrón: se convierte en su mejor versión.","Técnica clave: finger coiling en los mechones del marco del rostro; difusor en modo \"pixie diffusing\" (acercar el cabello al difusor apagado, encender, apagar, soltar); romper el cast al final con gel de fijación media-alta."]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA O-10 (quiere más rizo). El mensaje "su mejor versión" quedó sugerido en el borrador para validación de redacción de Keila.'),
  ('nota.f2.c01', 'es', 'nota', 240, '{"todas":[{"hecho":"ext.estadoCanas","op":"eq","valor":"menos_25"},{"hecho":"ext.situacionColor","op":"neq","valor":"tenida_cobertura"}]}'::jsonb, '{"textos":["Primeras canas (<25 %): melanina en descenso en hebras puntuales. El cabello circundante sigue mandando — el diagnóstico base de su tipo continúa siendo el principal y este módulo solo lo complementa. Matización solo si aparece amarillamiento.","Educación clave: no arrancar las canas. No \"salen siete más\" (mito), pero arrancarlas repetidamente maltrata el folículo y puede dañarlo."]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA C-01. Validación Keila: mito de arrancar la cana validado para el módulo educativo de la app.'),
  ('nota.f2.c02', 'es', 'nota', 241, '{"todas":[{"hecho":"canas25Mas","op":"verdadero"},{"hecho":"ext.amarillamientoCanas","op":"verdadero"}]}'::jsonb, '{"textos":["Amarillamiento de canas: la hebra blanca, sin melanina que la enmascare, absorbe y muestra todo — rayos UV, calor de herramientas, residuos de producto, minerales del agua dura, contaminación o nicotina. El amarillo es casi siempre extrínseco: tiene causa identificable.","Técnica clave — detective primero: ¿plancha muy caliente? ¿agua dura (considerar enjuague clarificante o quelante suave puntual)? ¿residuo de styling (clarificante 1 vez)? Tratar la causa evita matizar de por vida.","Protocolo de matización: máximo 1 vez por semana, tiempos de pausa cortos al inicio (la cana porosa toma el pigmento violeta rápido — pausas cortas evitan reflejos lila). Siempre intercalar hidratación: los matizadores resecan."]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA C-02 + reglas del cronograma CAN-1. Pregunta para Keila: ¿hay matizador violeta en el catálogo KEYSHOP?'),
  ('nota.f2.c03', 'es', 'nota', 242, '{"hecho":"ext.texturaCana","op":"en","valor":["mas_gruesa_aspera","patron_distinto"]}'::jsonb, '{"textos":["Cana rebelde — textura cambiada: la cana no es \"más fuerte\", es más seca e indisciplinada. Con la edad cambia la fibra y baja la producción de sebo, y la hebra blanca lo refleja primero. Plan: NUT-1 adaptado + disciplina sin agresión.","Técnica clave: disciplinar con secado dirigido y tensión suave de cepillo, nunca con plancha al máximo \"para domarla\". En patrones ondulados o rizados, producto extra y técnica localizada en esas hebras."]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA C-03. Validación Keila: la cana se identifica como hebra con alteración estructural; refuerzo localizado transversal según el servicio.'),
  ('nota.f2.c04', 'es', 'nota', 243, '{"hecho":"ext.estadoCanas","op":"eq","valor":"mas_50"}'::jsonb, '{"textos":["Cabello maduro (canas ≥50 %): la producción de sebo desciende con la edad — el cabello mayormente cano tiende a una sed estructural que no es daño, es fisiología. La rutina debe compensar lo que el cuero cabelludo ya no aporta: hidratación profunda semanal fija + nutrición ligera alternada.","Técnica clave: espaciar lavados, agua tibia (nunca caliente), funda de satén recomendada."]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA C-04 (cabello maduro reseco — MANT-1 reforzado).'),
  ('nota.f2.c05', 'es', 'nota', 244, '{"todas":[{"hecho":"tieneCanas","op":"verdadero"},{"hecho":"ext.situacionColor","op":"eq","valor":"en_transicion"}]}'::jsonb, '{"textos":["Transición a canas desde el tinte: un proyecto de 12 a 24 meses según el largo — dos cabellos conviviendo en una cabeza. El éxito depende menos de los productos y más de la estrategia visual y el acompañamiento emocional del proceso.","Estrategias posibles: (a) corte progresivo o radical; (b) transición difuminada con técnicas de color (la ejecución pertenece al módulo de colorimetría de Fase 3 o a colorista aliado); (c) transición libre con matización del segmento natural. La línea de demarcación se gestiona con estrategia visual — nunca con química improvisada.","Técnica clave: foto de progreso en cada visita para el Pasaporte Capilar — ver el avance sostiene la decisión en los meses difíciles de la línea de demarcación."]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA C-05 + CAN-2. Pregunta para Keila: ¿KEYSHOP ejecuta las técnicas de color de transición o se alía con colorista hasta Fase 3?'),
  ('nota.f2.c06', 'es', 'nota', 245, '{"todas":[{"hecho":"canas25Mas","op":"verdadero"},{"hecho":"ext.situacionColor","op":"eq","valor":"tenida_cobertura"},{"hecho":"tinteFrecuente","op":"verdadero"}]}'::jsonb, '{"textos":["Cobertura de canas con tinte frecuente: doble carga sobre la fibra — hebra madura, naturalmente más seca, sometida además a química frecuente. Es el perfil cano con más riesgo de daño acumulativo. Plan: reparación continua y suave + hábitos de protección del color (proteína suave quincenal o mensual según la prueba de elasticidad).","Técnica clave: retocar solo la raíz siempre que el objetivo lo permita. La cobertura de canas resistentes tiene técnica propia (pre-pigmentación, elección de base) que documentará el módulo de colorimetría de Fase 3."]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA C-06 (cobertura de canas con tinte frecuente).'),
  ('nota.f2.c07', 'es', 'nota', 246, '{"todas":[{"hecho":"tieneCanas","op":"verdadero"},{"hecho":"esLiso","op":"falso"}]}'::jsonb, '{"textos":["Cana en patrón ondulado o rizado: las hebras blancas pierden definición frente al resto del patrón. La cana, más seca y a veces con patrón levemente distinto, se \"sale del peinado\". No es un problema del rizo: es la sed puntual de esas hebras. El plan de definición de su tipo continúa + refuerzo localizado en las hebras canas.","Técnica clave: producto adicional y técnica localizada (finger coiling o twist suave) en los mechones canos del marco del rostro; hidratación profunda regular."]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA C-07. El ejemplo perfecto de condición transversal: se suma al diagnóstico base sin reemplazarlo. Sobre tipos 3–4 aplica igual (Entrega 4 §2.2).'),
  ('nota.f2.c08', 'es', 'nota', 247, '{"hecho":"ext.aparicionCanas","op":"eq","valor":"subita_temprana"}'::jsonb, '{"textos":["Tus primeras canas son el reflejo de tu genética única. Si consideras que su aparición ha sido extraordinariamente súbita, coméntalo de manera casual con tu médico en tu consulta de rutina, ¡pero sonríe!, la gran mayoría de las veces es herencia pura.","Para la estilista: el tono lo es todo — normalizar y dar opciones (lucirla, matizarla o cubrirla) sin empujar ninguna. La canicie no se \"trata\" cosméticamente: se cuida y, si la clienta quiere, se colorea. NO es bandera roja."]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA C-08 (canicie prematura). CORRECCIÓN DE KEILA APLICADA: el primer texto es VERBATIM del documento de validación (reemplaza la redacción del borrador; se elimina del PDF cualquier palabra que induzca a la hipocondría).'),
  ('nota.f2.a01', 'es', 'nota', 250, '{"hecho":"ext.situacionCaida","op":"en","valor":["en_evaluacion_medica","diagnostico_confirmado_manejo"]}'::jsonb, '{"textos":["Acompañamiento bajo manejo médico (A-01): el protagonista del tratamiento es el médico. El rol del salón es ser el mejor aliado posible — cuidar sin interferir, registrar la evolución y sostener el ánimo. Cuidado de mínima agresión durante todo el proceso: champú suave, sin procesos químicos nuevos, sin calor alto, sin tensión mecánica.","Antes de aplicar cualquier producto en el cuero cabelludo en cabina, confirmar con la clienta que no interfiere con lo indicado por su médico. El salón nunca sugiere modificar, complementar ni suspender un tratamiento médico.","Registrar evolución con fotos comparables (misma luz, mismo ángulo) SOLO con autorización expresa; celebrar los avances pequeños."]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA A-01. Línea jurídica validada por Keila (guion de derivación aprobado palabra por palabra).'),
  ('nota.f2.a02', 'es', 'nota', 251, '{"todas":[{"hecho":"ext.senalesCaida","op":"incluye","valor":"traccion_sienes"},{"hecho":"ext.senalesCaida","op":"noIncluye","valor":"zonas_lisas_brillantes"}]}'::jsonb, '{"textos":["Amar tu cabello también es soltarlo. La tensión constante en el mismo punto debilita la raíz hasta apagarla. Dale un respiro a tu línea frontal.","Tracción temprana (A-02) — donde el salón es protagonista: es la única forma de pérdida donde la estilista tiene poder causal directo. Intervención inmediata de hábitos: cero tensión por 8–12 semanas, rotación de peinados sueltos, límites de peso y tiempo de uso de extensiones, satén nocturno.","Revisión con fotos a las 8–12 semanas: si no aparece repoblación con vello fino o surgen zonas lisas y brillantes → derivar. La conversación es la técnica: explicar la relación causa-efecto sin culpabilizar y proponer alternativas de peinado que la clienta de verdad use."]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA A-02. CORRECCIÓN DE KEILA APLICADA: el primer texto es el copy oficial VERBATIM del documento de validación. Aprobada con máxima prioridad para la prevención en salones. Si hay zonas lisas y brillantes, gana la derivación (fibrosis).'),
  ('nota.f2.a03', 'es', 'nota', 252, '{"hecho":"ext.senalesCaida","op":"incluye","valor":"rotura_sin_bulbo"}'::jsonb, '{"textos":["Rotura masiva — no es caída (A-03): territorio 100 % cosmético. La fibra se quiebra pero el folículo está sano: hebras partidas sin bulbo, puntas cortas \"paradas\" a media cabellera. Es grave para la estética pero no es pérdida de cabello — y se comunica así, con alivio incluido.","Plan: REP-2 + suspensión total de la causa (calor, química, fricción) + corte sanitario de lo irreversible.","Técnica clave: mostrarle a la clienta la diferencia bulbo/no-bulbo con una de sus propias hebras — entender que \"no se le está cayendo\" cambia su ansiedad por completo."]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA A-03 (rotura masiva, no caída).'),
  ('nota.f2.a04', 'es', 'nota', 253, '{"hecho":"ext.situacionCaida","op":"eq","valor":"posparto_ventana"}'::jsonb, '{"textos":["Efluvio en resolución (A-04, p. ej. posparto): proceso generalmente autolimitado — el cabello que \"se guardó\" durante el embarazo se suelta de golpe (suele iniciar 2–4 meses después del parto). La fibra nueva ya viene en camino: los \"baby hairs\" del marco son señal de recuperación, no un problema.","Plan: paciencia informada + manejo cosmético del volumen mientras se resuelve — corte estratégico que redistribuya, productos voluminizadores, peinados que disimulen densidad. Nada vendido como \"freno de la caída\": la cosmética no detiene un efluvio y prometerlo erosiona la confianza.","Acordar revisión: si la caída intensa supera los ~6 meses o empeora, derivar (o re-derivar) para nueva evaluación."]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA A-04 (efluvio en resolución con causa identificada por su médico).'),
  ('nota.f2.a05', 'es', 'nota', 254, '{"hecho":"ext.situacionCaida","op":"eq","valor":"perdida_estable_camuflaje"}'::jsonb, '{"textos":["Camuflaje cosmético digno (A-05): verse bien durante el proceso no es vanidad — es salud emocional. El salón puede ofrecer soluciones honestas de apariencia inmediata sin prometer lo que no puede cumplir.","Menú de opciones según el caso: fibras capilares, polvos densificadores del cuero cabelludo, cortes y peinados que redistribuyen volumen, cambio de línea de raya.","Técnica clave: presentarlo como lo que es — apariencia hoy, sin efecto sobre el crecimiento. La honestidad es parte del servicio."]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA A-05. Pregunta para Keila: ¿incorporamos fibras/densificadores al catálogo KEYSHOP?'),
  ('nota.f2.r301', 'es', 'nota', 260, '{"todas":[{"hecho":"tipoRizoPrincipal","op":"eq","valor":"3C"},{"hecho":"densidad","op":"eq","valor":"alta"},{"hecho":"grosor","op":"eq","valor":"fino"}]}'::jsonb, '{"textos":["La paradoja del 3C fino (R3-01): necesita mucha agua pero poco peso — se apelmaza con cremas pesadas pero se reseca sin ellas. La solución no es más producto sino capas finas y frecuentes: \"menos cantidad, más veces\". Leave-in acuoso + gel, evitando mantecas en este perfil.","Técnica clave: aplicar por secciones pequeñas sobre cabello empapado, con squish; refrescos de agua + leave-in entre lavados en lugar de re-aplicar crema."]}'::jsonb, false, 'borrador', 'Entrega 4 · REGLA R3-01 · FUSIONAR: se conservan del motor las frecuencias (cronograma de rizos intacto) y de aquí solo el principio de capas ligeras. Validación Keila: "prohibiendo mantecas densas para evitar el colapso del volumen".'),
  ('nota.f2.r302', 'es', 'nota', 261, '{"todas":[{"hecho":"esRizado","op":"verdadero"},{"hecho":"ext.procesosQuimicos","op":"incluye","valor":"decoloracion"}]}'::jsonb, '{"textos":["Rizo 3 decolorado (R3-02): la fibra decolorada pierde memoria — el rizo se abre o se vuelve lacio-paja en las zonas tratadas. Se maneja con balance proteína-hidratación POR ZONAS y expectativa honesta: parte del patrón puede no volver.","Técnica clave: prueba de elasticidad POR ZONAS (no global); finger coiling en mechones decolorados para reeducar la forma mientras la fibra lo permita; styling que unifique texturas.","Cualquier retoque de color pasa por los guardarraíles del módulo de colorimetría (elasticidad como puerta)."]}'::jsonb, false, 'borrador', 'Entrega 4 · REGLA R3-02 · NUEVA: el motor nació antes del módulo de color. Es el puente oficial rizos ↔ colorimetría.'),
  ('nota.f2.t401', 'es', 'nota', 262, '{"hecho":"esAfro","op":"verdadero"}'::jsonb, '{"textos":["El encogimiento es dato, no defecto (T4-01): el encogimiento natural del tipo 4 puede superar el 75 % — es señal de elasticidad y salud, no de falta de crecimiento. Registrar SIEMPRE dos largos en el historial: natural y estirado suave. El Pasaporte Capilar muestra la curva de crecimiento real.","Técnica clave: medición del largo estirado sobre mechón húmedo, estirando suave sin tensión; siempre el mismo mechón de referencia (nuca o coronilla) para comparabilidad."]}'::jsonb, false, 'borrador', 'Entrega 4 · REGLA T4-01 · NUEVA (el motor no registra encogimiento). Validación Keila: "El software exigirá al estilista registrar dos medidas de longitud en el Pasaporte Capilar... la única vía científica para demostrar la tasa de crecimiento real". Dimensiones: largoNaturalCm / largoEstiradoCm.'),
  ('nota.f2.t402', 'es', 'nota', 263, '{"hecho":"esAfro","op":"verdadero"}'::jsonb, '{"textos":["Desenredado seguro — protocolo anti-rotura OBLIGATORIO en todo plan tipo 4 (T4-02): el tipo 4 se rompe por MANIPULACIÓN más que por química — cada curva de la hebra es un punto estructuralmente débil. Nunca en seco; siempre con acondicionador de deslizamiento; por secciones; de puntas a raíz; dedos primero, peine de dientes anchos después. Frecuencia: la mínima necesaria según el estilo.","Si un nudo no cede con los dedos y acondicionador, se corta el nudo — no se arranca la sección. Un nudo perdido cuesta menos que diez hebras rotas."]}'::jsonb, false, 'borrador', 'Entrega 4 · REGLA T4-02 · FUSIONAR: eleva de consejo a PROTOCOLO obligatorio. El detangle del cuidado en casa del motor se conserva; esta nota agrega el protocolo y la regla del nudo.'),
  ('nota.f2.t403_porosidad_alta', 'es', 'nota', 264, '{"todas":[{"hecho":"esAfro","op":"verdadero"},{"hecho":"porosidad","op":"eq","valor":"alta"}]}'::jsonb, '{"textos":["Sellado en capas (T4-03): por geometría, el sebo no logra recorrer la espiral — el tipo 4 es el cabello más seco que existe. El agua que entra debe sellarse en capas o se evapora en horas. Con porosidad ALTA: orden LOC (líquido → aceite → crema) con sellado pesado (mantecas como karité). Aplicar sobre cabello EMPAPADO por secciones — sellar cabello húmedo-casi-seco es sellar la mitad del agua."]}'::jsonb, false, 'borrador', 'Entrega 4 · REGLA T4-03 · FUSIONAR: el motor ya usa vocabulario LOC/LCO (casa.dia_lavado.porosidad_alta) — esta nota aporta la elección del orden según porosidad y la aplicación sobre cabello empapado.'),
  ('nota.f2.t403_porosidad_baja', 'es', 'nota', 265, '{"todas":[{"hecho":"esAfro","op":"verdadero"},{"hecho":"porosidad","op":"eq","valor":"baja"}]}'::jsonb, '{"textos":["Sellado en capas (T4-03): con porosidad BAJA el orden es LCO ligero (líquido → crema → aceite), productos acuosos, y clarificante mensual para evitar acumulación. Aplicar sobre cabello EMPAPADO por secciones."]}'::jsonb, false, 'borrador', 'Entrega 4 · REGLA T4-03 (variante porosidad baja).'),
  ('nota.f2.t404', 'es', 'nota', 266, '{"todas":[{"hecho":"esAfro","op":"verdadero"},{"hecho":"ext.objetivoEstilo","op":"eq","valor":"estirado_sin_calor"}]}'::jsonb, '{"textos":["Estiramiento sin calor (T4-04): el calor frecuente en tipo 4 es la vía rápida a la pérdida permanente de patrón. El estiramiento mecánico suave logra el mismo efecto visual sin hipotecar el rizo. Técnicas según el resultado: twist-out y braid-out (definición estirada), banding y threading africano (máximo estiramiento). Siempre sobre cabello con producto y secado COMPLETO antes de soltar.","Técnica clave: soltar solo con el cabello 100 % seco y con las manos apenas aceitadas (el frizz nace de soltar húmedo o con manos secas). Deshacer en la dirección del twist, nunca en contra."]}'::jsonb, false, 'borrador', 'Entrega 4 · REGLA T4-04 · NUEVA: el motor está optimizado para definición; el estiramiento sin calor es la otra mitad del menú tipo 4.'),
  ('nota.f2.t405', 'es', 'nota', 267, '{"hecho":"protectorInstalado","op":"verdadero"}'::jsonb, '{"textos":["El peinado protector bien hecho (T4-05): el protector protege SOLO si no tensa — mal instalado es la causa número uno de alopecia por tracción. El dolor durante la instalación no es normal: es la bandera. Instalación sin dolor; bordes y línea frontal SIEMPRE con holgura; peso de extensiones moderado; duración máxima orientativa de 4–8 semanas; descanso de 1–2 semanas entre instalaciones.","La conversación previa es la técnica: acordar con la clienta el tamaño de secciones, la tensión y el calendario de retiro ANTES de trenzar. Agendar el retiro como cita al momento de instalar.","Tras retirar: descanso de 1–2 semanas y día de lavado completo antes de la siguiente instalación."]}'::jsonb, false, 'borrador', 'Entrega 4 · REGLA T4-05 · NUEVA: regla de servicio y educación; su impacto preventivo (tracción, A-02) la hace prioritaria.'),
  ('nota.f2.t406', 'es', 'nota', 268, '{"hecho":"protectorInstalado","op":"verdadero"}'::jsonb, '{"textos":["El cuero cabelludo bajo el protector (T4-06): bajo trenzas, el cuero cabelludo sigue vivo — acumula sebo, sudor y producto. La humedad atrapada tras un lavado mal secado produce olor, picor e irritación: el enemigo silencioso de las instalaciones largas. Limpieza del cuero cabelludo cada 1–2 semanas con champú diluido y aplicador, hidratación ligera de raíces, y secado COMPLETO tras cada mojada, sin excepción.","Bandera dentro de la regla: picor intenso, dolor, pústulas o mal olor persistente → retirar la instalación; si la piel está comprometida, protocolo de derivación."]}'::jsonb, false, 'borrador', 'Entrega 4 · REGLA T4-06 · NUEVA: pareja inseparable de T4-05.'),
  ('nota.f2.t407', 'es', 'nota', 269, '{"todas":[{"hecho":"esAfro","op":"verdadero"},{"hecho":"transicion","op":"verdadero"}]}'::jsonb, '{"textos":["Transición tipo 4 — la línea que se rompe (T4-07): la unión entre lo natural y lo procesado es el punto más frágil de cualquier transición, y en tipo 4 doblemente — la curva natural más cerrada multiplica el estrés mecánico justo en la línea de demarcación. Manipulación mínima absoluta, protectores de BAJA tensión como aliados, fortalecimiento suave alternado con hidratación, y cortes programados más frecuentes que en una transición tipo 2–3.","Técnica clave: peinados que no carguen peso sobre la línea de demarcación; desenredado extra-paciente en esa franja. Si la rotura se concentra en la línea: bajar manipulación a mínimos, fortalecer la franja y adelantar el corte programado."]}'::jsonb, false, 'borrador', 'Entrega 4 · REGLA T4-07 · FUSIONAR con las reglas de transición del motor (las notas del motor se conservan y esta agrega el énfasis tipo 4). Incluye la bandera de rotura en línea de demarcación (Entrega 4 §8).'),
  ('nota.f2.t408_definido', 'es', 'nota', 270, '{"todas":[{"hecho":"esAfro","op":"verdadero"},{"hecho":"ext.objetivoEstilo","op":"eq","valor":"definido_natural"}]}'::jsonb, '{"textos":["Tipo 4 en clima húmedo — aliada (T4-08): en estilos definidos al natural la humedad ayuda — hidrata el ambiente y el patrón la celebra. Aprovecharla: refrescos de agua + leave-in, sin miedo."]}'::jsonb, false, 'borrador', 'Entrega 4 · REGLA T4-08 (mitad "definido"). VERIFICAR contra reglas de clima del motor; la gestión de expectativas de estilos estirados es la parte probablemente nueva.'),
  ('nota.f2.t408_estirado', 'es', 'nota', 271, '{"todas":[{"hecho":"esAfro","op":"verdadero"},{"hecho":"ext.objetivoEstilo","op":"eq","valor":"estirado_sin_calor"}]}'::jsonb, '{"textos":["Tipo 4 en clima húmedo — enemiga de los estilos estirados (T4-08): la humedad revierte horas de trabajo en una caminata. Sellado antihumectante + expectativa honesta de duración — el sistema lo dice antes de que la clienta lo descubra mojada. La gestión de expectativas ES la técnica: indicar cuánto durará cada estilo en el clima local, para que la clienta elija informada."]}'::jsonb, false, 'borrador', 'Entrega 4 · REGLA T4-08 (mitad "estirado" — probablemente NUEVA).'),
  ('nota.f2.protector_dolor', 'es', 'nota', 272, '{"hecho":"ext.senalesProtector","op":"incluye","valor":"dolor_tension_bultitos"}'::jsonb, '{"textos":["BANDERA DE TENSIÓN: dolor, tirantez o \"bultitos\" durante o después de una instalación = tracción en curso. Detener o aflojar la instalación de inmediato. El dolor nunca es el precio de un peinado. Dolor o tensión en cualquier momento = señal de retiro, no de aguante."]}'::jsonb, false, 'borrador', 'Entrega 4 · banderas específicas de tipos 3–4: acción operativa inmediata (no es derivación médica por sí sola; la derivación aplica si hay piel comprometida).'),
  ('nota.f2.protector_picor', 'es', 'nota', 273, '{"hecho":"ext.senalesProtector","op":"incluye","valor":"picor_mal_olor"}'::jsonb, '{"textos":["BANDERA BAJO EL PROTECTOR: picor intenso o mal olor persistente = cuero cabelludo comprometido por humedad atrapada o higiene insuficiente. Retirar la instalación. Si la piel muestra lesiones o pústulas, aplica el protocolo de derivación."]}'::jsonb, false, 'borrador', 'Entrega 4 · banderas específicas de tipos 3–4 + T4-06. Con pústulas/lesiones marcadas, la derivación médica gana (derivacion.f2.protector_lesiones).'),
  ('producto.f2.eq1', 'es', 'producto_resumen', 100, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"EQ-1"}'::jsonb, '{"textos":["Champú equilibrante suave apto para uso frecuente","Acondicionador ligero solo de medios a puntas","Exfoliante capilar suave (1 vez por semana o quincena)"]}'::jsonb, false, 'borrador', 'Entrega 1 · productos EQ-1 (L-01, L-02, L-07, O-07).'),
  ('producto.f2.eq1_sellado_puntas', 'es', 'producto_resumen', 101, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"hecho":"oleosidadAlta","op":"verdadero"},{"alguna":[{"hecho":"estadoPuntas","op":"regex","valor":"abiertas"},{"hecho":"porosidad","op":"eq","valor":"alta"}]}]}'::jsonb, '{"textos":["Sérum de puntas sin enjuague (siliconas solubles o aceites secos ligeros tipo jojoba)","Mascarilla hidratante quincenal aplicada solo de medios a puntas"]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA L-02: EQ-1 + sellado de puntas.'),
  ('producto.f2.volumen', 'es', 'producto_resumen', 102, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"hecho":"ext.objetivoPrincipal","op":"eq","valor":"volumen"}]}'::jsonb, '{"textos":["Champú de volumen","Acondicionador solo en puntas","Mousse ligera de raíz (aplicar en húmedo, antes del secado)"]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA L-07 (busca volumen).'),
  ('producto.f2.rep1', 'es', 'producto_resumen', 103, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"REP-1"}'::jsonb, '{"textos":["Champú sin sulfatos fuertes","Mascarilla hidratante semanal","Reconstructor con proteína hidrolizada quincenal","Protector térmico en cada exposición a calor"]}'::jsonb, false, 'borrador', 'Entrega 1 · productos REP-1 (L-03, L-09, O-06).'),
  ('producto.f2.rep2', 'es', 'producto_resumen', 104, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"REP-2"}'::jsonb, '{"textos":["Reconstructor proteico (queratina o colágeno hidrolizado)","Mascarilla hidratante para alternar y evitar sobrecarga proteica","Leave-in con ceramidas"]}'::jsonb, false, 'borrador', 'Entrega 1 · productos REP-2 (L-04, O-04, A-03).'),
  ('producto.f2.nut1', 'es', 'producto_resumen', 105, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"NUT-1"}'::jsonb, '{"textos":["Acondicionador nutritivo","Crema de peinar ligera","Aceite seco para sellar (2–3 gotas de argán o jojoba en medios y puntas)","Spray antifrizz o antihumectante para días críticos"]}'::jsonb, false, 'borrador', 'Entrega 1 · productos NUT-1 (L-05, O-08).'),
  ('producto.f2.def1', 'es', 'producto_resumen', 106, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"DEF-1"}'::jsonb, '{"textos":["Crema de peinar ligera + gel de fijación ligera-media (técnica crema + gel)","Toalla de microfibra"]}'::jsonb, false, 'borrador', 'Entrega 1 · productos DEF-1 (O-01: mousse/espuma en vez de cremas densas; O-02 secuencia completa).'),
  ('producto.f2.def2', 'es', 'producto_resumen', 107, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"DEF-2"}'::jsonb, '{"textos":["Mascarilla de hidratación profunda semanal","Leave-in","Gel de fijación media-alta","Antihumectante reservado para días u ocasiones críticas"]}'::jsonb, false, 'borrador', 'Entrega 1 · productos DEF-2 (O-03, O-10 con porosidad alta).'),
  ('producto.f2.post_alisado', 'es', 'producto_resumen', 108, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"hecho":"alisadoVigente","op":"verdadero"}]}'::jsonb, '{"textos":["Champú sin sulfatos ni sal","Mascarilla hidratante","Sérum térmico si usa plancha de retoque"]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA L-06 (protocolo post-alisado).'),
  ('producto.f2.cuero_seco', 'es', 'producto_resumen', 109, '{"todas":[{"hecho":"esLiso","op":"verdadero"},{"alguna":[{"hecho":"ext.descamacion","op":"eq","valor":"fina_blanca"},{"hecho":"ext.tipoCueroCabelludo","op":"eq","valor":"seco"}]}]}'::jsonb, '{"textos":["Champú suave hidratante","Tónico o sérum de cuero cabelludo con pantenol o aloe"]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA L-08 (cuero cabelludo seco).'),
  ('producto.f2.detox', 'es', 'producto_resumen', 110, '{"todas":[{"hecho":"esOndulado","op":"verdadero"},{"hecho":"buildUp","op":"verdadero"}]}'::jsonb, '{"textos":["Champú clarificante (máximo 1 vez al mes)","Después del detox: línea de definición sin siliconas insolubles"]}'::jsonb, false, 'borrador', 'Entrega 1 · REGLA O-05 (detox + reinicio).'),
  ('producto.f2.can1', 'es', 'producto_resumen', 111, '{"todas":[{"hecho":"canas25Mas","op":"verdadero"},{"hecho":"ext.amarillamientoCanas","op":"verdadero"}]}'::jsonb, '{"textos":["Champú o mascarilla matizadora violeta (máximo 1 vez por semana, pausas cortas al inicio)","Hidratación intercalada (los matizadores resecan)","Protector térmico y UV"]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA C-02 / cronograma CAN-1.'),
  ('producto.f2.color_canas', 'es', 'producto_resumen', 112, '{"todas":[{"hecho":"canas25Mas","op":"verdadero"},{"hecho":"ext.situacionColor","op":"eq","valor":"tenida_cobertura"}]}'::jsonb, '{"textos":["Línea de protección de color sin sulfatos","Hidratación semanal + proteína suave según prueba de elasticidad"]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA C-06 (cobertura con tinte frecuente).'),
  ('producto.f2.prot1', 'es', 'producto_resumen', 113, '{"hecho":"protectorInstalado","op":"verdadero"}'::jsonb, '{"textos":["Champú suave diluible con botella aplicadora","Spray hidratante acuoso","Aceite ligero para raíces","Accesorios de satén para dormir con la instalación"]}'::jsonb, false, 'borrador', 'Entrega 4 · productos PROT-1 (T4-05, T4-06).'),
  ('producto.f2.camuflaje', 'es', 'producto_resumen', 114, '{"hecho":"ext.situacionCaida","op":"eq","valor":"perdida_estable_camuflaje"}'::jsonb, '{"textos":["Fibras y polvos densificadores (resistentes al roce, se retiran con el lavado)","Spray fijador suave"]}'::jsonb, false, 'borrador', 'Entrega 2 · REGLA A-05 (camuflaje cosmético digno).'),
  ('casa.f2.lavado_tipo4', 'es', 'cuidado_casa', 100, '{"hecho":"esAfro","op":"verdadero"}'::jsonb, '{"campo":"diaLavado","textos":["PROTOCOLO DÍA DE LAVADO TIPO 4 (2–4 horas): pre-acondicionado (pre-poo) con aceite o acondicionador sobre cabello seco, por secciones, 20–30 minutos","Seccionar en 4–8 partes y MANTENER las secciones durante todo el proceso (pinzas o twists)","Limpieza por secciones, masajeando solo el cuero cabelludo con yemas; la espuma limpia los largos al enjuagar","Acondicionado profundo: mascarilla con 15–30 minutos de pausa; calor suave opcional (gorro térmico)","Desenredado DENTRO del acondicionador: dedos primero, peine de dientes anchos después, de puntas a raíz","Enjuague con agua tibia terminando en fría; sellado en capas sobre cabello empapado según porosidad","Secado completo sin manipular: aire libre o difusor en frío/medio — cabello tipo 4 húmedo y manipulado = rotura"]}'::jsonb, false, 'borrador', 'Entrega 4 §4 · protocolo de referencia, validación Keila: "Introducción obligatoria en la app del Protocolo de Día de Lavado Tipo 4". Nota de producto pendiente: duración extendida automática en agenda para servicios tipo 4 (2–4 h).'),
  ('casa.f2.eq1_evitar', 'es', 'cuidado_casa', 101, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"EQ-1"}'::jsonb, '{"campo":"evitar","textos":["Nada cremoso ni oleoso en la raíz, en ninguna sesión","Agua caliente (usar tibia, con enjuague final frío)","Exfoliar el cuero cabelludo más de 1 vez por semana"]}'::jsonb, false, 'borrador', 'Entrega 1 · reglas del cronograma EQ-1.'),
  ('casa.f2.rep2_evitar', 'es', 'cuidado_casa', 102, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"REP-2"}'::jsonb, '{"campo":"evitar","textos":["Cero calor y cero químicos durante las 4 semanas, sin excepciones","Proteína sin hidratación (siempre alternar: la proteína sin hidratación rigidiza)"]}'::jsonb, false, 'borrador', 'Entrega 1 · reglas del cronograma REP-2.'),
  ('casa.f2.rep1_evitar', 'es', 'cuidado_casa', 103, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"REP-1"}'::jsonb, '{"campo":"evitar","textos":["Calor sin protector térmico (protector obligatorio si hay calor)","Plancha más de 1 vez por semana durante el mes"]}'::jsonb, false, 'borrador', 'Entrega 1 · reglas del cronograma REP-1 (base de hidratación con proteína quincenal).'),
  ('casa.f2.nut1_evitar', 'es', 'cuidado_casa', 104, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"NUT-1"}'::jsonb, '{"campo":"evitar","textos":["Aceites y mantecas en la raíz (solo de medios a puntas)"]}'::jsonb, false, 'borrador', 'Entrega 1 · reglas del cronograma NUT-1. En días de humedad extrema: antihumectante como capa final.'),
  ('casa.f2.def_dia_lavado', 'es', 'cuidado_casa', 105, '{"hecho":"tratamientoPrincipal","op":"regex","valor":"DEF-1|DEF-2"}'::jsonb, '{"campo":"diaLavado","textos":["El styling se aplica siempre sobre cabello muy húmedo","No tocar mientras seca; romper el cast solo cuando esté 100 % seco"]}'::jsonb, false, 'borrador', 'Entrega 1 · reglas de los cronogramas DEF-1 y DEF-2.'),
  ('casa.f2.prot1_dia_lavado', 'es', 'cuidado_casa', 106, '{"hecho":"protectorInstalado","op":"verdadero"}'::jsonb, '{"campo":"diaLavado","textos":["Limpieza del cuero cabelludo con champú diluido y botella aplicadora","Secado COMPLETO tras cada mojada, sin excepción (humedad atrapada = olor, picor e irritación)"]}'::jsonb, false, 'borrador', 'Entrega 4 · PROT-1 / T4-06.'),
  ('casa.f2.prot1_nocturno', 'es', 'cuidado_casa', 107, '{"hecho":"protectorInstalado","op":"verdadero"}'::jsonb, '{"campo":"nocturno","textos":["Dormir con accesorios de satén mientras dure la instalación"]}'::jsonb, false, 'borrador', 'Entrega 4 · T4-05.'),
  ('casa.f2.prot1_evitar', 'es', 'cuidado_casa', 108, '{"hecho":"protectorInstalado","op":"verdadero"}'::jsonb, '{"campo":"evitar","textos":["Aguantar dolor o tensión: es señal de retiro, no de aguante","Dejar la instalación más de 4–8 semanas sin evaluación"]}'::jsonb, false, 'borrador', 'Entrega 4 · PROT-1 / T4-05.')
on conflict (clave, locale) do nothing;

insert into public.kb_dimensiones
  (clave, locale, etiqueta, descripcion, tipo, opciones, bandera_medica, estado)
values
  ('estadoCanas', 'es', 'Estado de canas', 'Proporción aproximada de canas visibles.', 'opcion', '[{"valor":"sin_canas","etiqueta":"Sin canas"},{"valor":"menos_25","etiqueta":"Menos del 25%"},{"valor":"entre_25_50","etiqueta":"Entre 25% y 50%"},{"valor":"mas_50","etiqueta":"Más del 50%"}]'::jsonb, false, 'publicada'),
  ('densidadPorZonas', 'es', 'Densidad por zonas', 'Zonas con densidad notablemente menor al resto.', 'multi', '[{"valor":"uniforme","etiqueta":"Uniforme (sin zonas ralas)"},{"valor":"entradas","etiqueta":"Entradas despobladas"},{"valor":"coronilla","etiqueta":"Coronilla rala"},{"valor":"laterales","etiqueta":"Laterales débiles"}]'::jsonb, false, 'publicada'),
  ('senalesAlopecia', 'es', 'Señales de alopecia', 'Señales clínicas observables. Las marcadas como médicas generan SIEMPRE derivación a dermatólogo.', 'multi', '[{"valor":"sin_senales","etiqueta":"Sin señales"},{"valor":"caida_estacional","etiqueta":"Caída estacional leve"},{"valor":"placas_sin_cabello","etiqueta":"Placas sin cabello (calvas localizadas)","banderaMedica":true},{"valor":"perdida_difusa_severa","etiqueta":"Pérdida difusa severa (cuero muy visible)","banderaMedica":true},{"valor":"retroceso_linea_frontal","etiqueta":"Retroceso de la línea frontal","banderaMedica":true}]'::jsonb, true, 'publicada'),
  ('tipoCueroCabelludo', 'es', 'Tipo de cuero cabelludo', 'Estado general del cuero cabelludo. Los estados marcados como médicos generan SIEMPRE derivación a dermatólogo.', 'opcion', '[{"valor":"normal","etiqueta":"Normal"},{"valor":"graso","etiqueta":"Graso"},{"valor":"seco","etiqueta":"Seco"},{"valor":"sensible","etiqueta":"Sensible"},{"valor":"dermatitis_leve","etiqueta":"Dermatitis leve / caspa"},{"valor":"dermatitis_severa","etiqueta":"Dermatitis severa (placas, inflamación)","banderaMedica":true},{"valor":"psoriasis_sospecha","etiqueta":"Sospecha de psoriasis","banderaMedica":true},{"valor":"lesiones_abiertas","etiqueta":"Lesiones abiertas o costras","banderaMedica":true}]'::jsonb, true, 'publicada'),
  ('procesosQuimicos', 'es', 'Procesos químicos previos', 'Procesos químicos aplicados en los últimos 12 meses.', 'multi', '[{"valor":"ninguno","etiqueta":"Ninguno"},{"valor":"tinte","etiqueta":"Tinte / coloración"},{"valor":"decoloracion","etiqueta":"Decoloración / mechas"},{"valor":"alisado","etiqueta":"Alisado permanente / keratina"},{"valor":"permanente","etiqueta":"Permanente (rizado químico)"},{"valor":"henna","etiqueta":"Henna / tintes vegetales"}]'::jsonb, false, 'publicada'),
  ('grasaRaiz', 'es', '¿Qué tan rápido se engrasa la raíz?', 'Oleosidad percibida del cuero cabelludo (Entrega 1).', 'opcion', '[{"valor":"mismo_dia","etiqueta":"El mismo día del lavado"},{"valor":"1_2_dias","etiqueta":"A los 1-2 días"},{"valor":"3_mas_dias","etiqueta":"A los 3 días o más"}]'::jsonb, false, 'borrador'),
  ('volumenRaiz', 'es', 'Volumen en la raíz', 'Cómo luce el volumen de raíz (tipo 1).', 'opcion', '[{"valor":"plano","etiqueta":"Plano / pegado al cráneo"},{"valor":"medio","etiqueta":"Medio"},{"valor":"abundante","etiqueta":"Con cuerpo"}]'::jsonb, false, 'borrador'),
  ('nivelFrizz', 'es', 'Nivel de frizz', 'En tipo 2 suele ser síntoma de deshidratación; en 1C, de cutícula abierta y estática (Entrega 1).', 'opcion', '[{"valor":"bajo","etiqueta":"Bajo"},{"valor":"medio","etiqueta":"Medio"},{"valor":"alto","etiqueta":"Alto"}]'::jsonb, false, 'borrador'),
  ('descamacion', 'es', 'Descamación del cuero cabelludo', 'La descamación fina y blanca sin enrojecimiento es resequedad simple (L-08). Con placas, enrojecimiento o dolor es señal médica: derivación obligatoria.', 'opcion', '[{"valor":"sin_descamacion","etiqueta":"Sin descamación"},{"valor":"fina_blanca","etiqueta":"Fina y blanca, sin enrojecimiento"},{"valor":"placas_enrojecimiento","etiqueta":"Placas gruesas, enrojecimiento, exudado o dolor","banderaMedica":true}]'::jsonb, true, 'borrador'),
  ('objetivoPrincipal', 'es', 'Objetivo principal', 'Una sola opción dominante: ordena el plan cuando varias reglas aplican (Entrega 1).', 'opcion', '[{"valor":"volumen","etiqueta":"Volumen"},{"valor":"control_frizz","etiqueta":"Control de frizz / estática"},{"valor":"brillo","etiqueta":"Brillo"},{"valor":"reparacion","etiqueta":"Reparación"},{"valor":"definicion","etiqueta":"Definición de onda"},{"valor":"mas_rizo","etiqueta":"Maximizar definición hacia rizo"},{"valor":"mantenimiento","etiqueta":"Mantenimiento"}]'::jsonb, false, 'borrador'),
  ('frecuenciaTinte', 'es', 'Frecuencia de coloración', 'Activa reglas de daño acumulativo por color (L-09, C-06).', 'opcion', '[{"valor":"sin_tinte","etiqueta":"No se tiñe"},{"valor":"cada_3_6_semanas","etiqueta":"Cada 3–6 semanas (cobertura)"},{"valor":"cada_8_semanas_o_menos","etiqueta":"Cada 8 semanas o menos"},{"valor":"esporadico","etiqueta":"Esporádico (más de 8 semanas)"}]'::jsonb, false, 'borrador'),
  ('acumulacionProducto', 'es', 'Acumulación de producto (build-up)', 'Uso habitual de siliconas insolubles, ceras o aceites minerales. Activa el detox antes que cualquier regla de definición (O-05).', 'opcion', '[{"valor":"si","etiqueta":"Sí"},{"valor":"no","etiqueta":"No"}]'::jsonb, false, 'borrador'),
  ('definicionOnda', 'es', '¿Qué tan definida luce la onda hoy?', 'Estado actual del patrón en tipo 2 (Entrega 1 §3.2).', 'opcion', '[{"valor":"definida","etiqueta":"Definida"},{"valor":"se_aplasta","etiqueta":"Se aplasta a las pocas horas"},{"valor":"sin_forma","etiqueta":"Sin forma / apagada"}]'::jsonb, false, 'borrador'),
  ('distribucionCanas', 'es', 'Distribución de las canas', 'Las canas del marco del rostro son las más visibles: priorizan técnica localizada (Entrega 2).', 'opcion', '[{"valor":"sienes","etiqueta":"Sienes"},{"valor":"corona","etiqueta":"Corona"},{"valor":"marco_rostro","etiqueta":"Marco del rostro"},{"valor":"difusa","etiqueta":"Difusa"}]'::jsonb, false, 'borrador'),
  ('amarillamientoCanas', 'es', '¿Las canas muestran tonos amarillos o apagados?', 'El amarillo es casi siempre extrínseco: calor, agua dura, residuos, UV o nicotina (C-02).', 'booleano', NULL, false, 'borrador'),
  ('texturaCana', 'es', 'Textura de la cana', 'Activa C-03 (cana rebelde) y C-07 (cana en patrón ondulado/rizado).', 'opcion', '[{"valor":"igual","etiqueta":"Igual al resto"},{"valor":"mas_gruesa_aspera","etiqueta":"Más gruesa / áspera"},{"valor":"patron_distinto","etiqueta":"Patrón distinto"}]'::jsonb, false, 'borrador'),
  ('situacionColor', 'es', 'Situación de color', 'La dimensión que más cambia el plan del módulo canas: activa C-05 o C-06.', 'opcion', '[{"valor":"natural","etiqueta":"Natural"},{"valor":"tenida_cobertura","etiqueta":"Teñida (cobertura)"},{"valor":"en_transicion","etiqueta":"En transición"},{"valor":"quiere_transicion","etiqueta":"Quiere iniciar transición"}]'::jsonb, false, 'borrador'),
  ('objetivoCana', 'es', 'Objetivo con la cana', 'Decisión de la clienta, nunca del sistema: Velli presenta opciones sin empujar (Entrega 2).', 'opcion', '[{"valor":"lucirla","etiqueta":"Lucirla"},{"valor":"matizarla","etiqueta":"Matizarla"},{"valor":"cubrirla","etiqueta":"Cubrirla"},{"valor":"transicionar","etiqueta":"Transicionar"}]'::jsonb, false, 'borrador'),
  ('aparicionCanas', 'es', 'Aparición de las canas', 'La canicie temprana súbita activa el mensaje sereno validado por Keila (C-08). NO es bandera roja.', 'opcion', '[{"valor":"gradual","etiqueta":"Gradual, con los años"},{"valor":"subita_temprana","etiqueta":"Abundante y rápida antes de los ~25 años"}]'::jsonb, false, 'borrador'),
  ('senalesCaida', 'es', 'Señales de caída o pérdida (guía de cabina)', 'Guía de reconocimiento de la Entrega 2: la primera pregunta es ¿rotura o caída? Rotura: hebras partidas sin bulbo (territorio cosmético). Caída: la hebra sale completa con bulbo blanquecino. Las señales médicas generan SIEMPRE derivación a dermatólogo.', 'multi', '[{"valor":"sin_senales","etiqueta":"Sin señales"},{"valor":"caida_normal","etiqueta":"Caída dentro de lo normal (hasta 50–100 hebras/día)"},{"valor":"rotura_sin_bulbo","etiqueta":"Rotura: hebras partidas sin bulbo, puntitas \"paradas\""},{"valor":"traccion_sienes","etiqueta":"Raleo en sienes/línea frontal con historia de tensión crónica"},{"valor":"parches_redondos","etiqueta":"Parches redondos u ovalados, lisos y bien definidos","banderaMedica":true},{"valor":"caida_difusa_subita","etiqueta":"Caída difusa, súbita y abundante (últimos 1–3 meses)","banderaMedica":true},{"valor":"raya_ensancha","etiqueta":"Raya que se ensancha / retroceso frontal / coronilla cada vez más fina","banderaMedica":true},{"valor":"zonas_lisas_brillantes","etiqueta":"Zonas lisas y brillantes sin vello (posible fibrosis)","banderaMedica":true},{"valor":"cuero_inflamado_pustulas","etiqueta":"Inflamación, pústulas, dolor o descamación severa","banderaMedica":true}]'::jsonb, true, 'borrador'),
  ('situacionCaida', 'es', 'Situación frente a la caída', 'Activa las reglas de acompañamiento A-01 a A-05 (clienta derivada, en manejo médico, posparto o camuflaje).', 'opcion', '[{"valor":"sin_caida","etiqueta":"Sin caída relevante"},{"valor":"en_evaluacion_medica","etiqueta":"Derivada / en evaluación médica"},{"valor":"diagnostico_confirmado_manejo","etiqueta":"En tratamiento dermatológico"},{"valor":"posparto_ventana","etiqueta":"Posparto dentro de la ventana esperada (2–4 meses)"},{"valor":"perdida_estable_camuflaje","etiqueta":"Pérdida estable: quiere verse mejor hoy"}]'::jsonb, false, 'borrador'),
  ('objetivoEstilo', 'es', 'Objetivo de estilo (tipos 3–4)', 'Enruta las técnicas: wash and go, twist-out/banding o instalación protectora (Entrega 4).', 'opcion', '[{"valor":"definido_natural","etiqueta":"Definido al natural"},{"valor":"estirado_sin_calor","etiqueta":"Estirado sin calor"},{"valor":"protector","etiqueta":"Peinado protector"}]'::jsonb, false, 'borrador'),
  ('protectorEnUso', 'es', 'Peinado protector en uso', 'Activa PROT-1, T4-05 y T4-06; controla tiempos máximos y descansos.', 'opcion', '[{"valor":"ninguno","etiqueta":"Ninguno"},{"valor":"trenzas","etiqueta":"Trenzas"},{"valor":"twists","etiqueta":"Twists"},{"valor":"extensiones","etiqueta":"Extensiones"}]'::jsonb, false, 'borrador'),
  ('senalesProtector', 'es', 'Señales bajo el protector', 'Dolor o tensión = aflojar o retirar. Pústulas o lesiones en la piel = derivación (Entrega 4 §8).', 'multi', '[{"valor":"sin_molestias","etiqueta":"Sin molestias"},{"valor":"dolor_tension_bultitos","etiqueta":"Dolor, tirantez o \"bultitos\""},{"valor":"picor_mal_olor","etiqueta":"Picor intenso o mal olor persistente"},{"valor":"pustulas_lesiones","etiqueta":"Pústulas o lesiones en la piel","banderaMedica":true}]'::jsonb, true, 'borrador'),
  ('largoNaturalCm', 'es', 'Largo natural (cm, en encogimiento)', 'T4-01: registrar SIEMPRE dos largos — el Pasaporte muestra el crecimiento real que el espejo esconde.', 'texto', NULL, false, 'borrador'),
  ('largoEstiradoCm', 'es', 'Largo estirado (cm, tracción suave en húmedo)', 'T4-01: medir sobre el mismo mechón de referencia (nuca o coronilla).', 'texto', NULL, false, 'borrador'),
  ('manipulacion', 'es', 'Frecuencia de desenredado y peinado', 'El tipo 4 se rompe por manipulación: este dato calibra el plan (T4-02).', 'opcion', '[{"valor":"diaria","etiqueta":"Diaria"},{"valor":"varias_semana","etiqueta":"Varias veces por semana"},{"valor":"semanal_o_menos","etiqueta":"Semanal o menos"}]'::jsonb, false, 'borrador')
on conflict (clave, locale) do nothing;

insert into public.kb_flujos
  (clave, locale, tipos_cabello, definicion, estado)
values
  ('flujo.liso', 'es', ARRAY['1A', '1B', '1C']::text[], '{"titulo":"Preguntas para cabello liso","descripcion":"En tipo 1 el cuero cabelludo es protagonista: el sebo viaja libre por la hebra recta. Desaparecen las preguntas de definición y entran oleosidad, volumen e historial.","preguntas":[{"clave":"grasaRaiz","etiqueta":"¿Qué tan rápido se engrasa la raíz?","tipo":"opcion","opciones":[{"valor":"mismo_dia","etiqueta":"El mismo día del lavado"},{"valor":"1_2_dias","etiqueta":"A los 1-2 días"},{"valor":"3_mas_dias","etiqueta":"A los 3 días o más"}]},{"clave":"volumenRaiz","etiqueta":"¿Cómo es el volumen en la raíz?","tipo":"opcion","opciones":[{"valor":"plano","etiqueta":"Plano / pegado al cráneo"},{"valor":"medio","etiqueta":"Medio"},{"valor":"abundante","etiqueta":"Con cuerpo"}]},{"clave":"tipoCueroCabelludo","etiqueta":"Tipo de cuero cabelludo","ayuda":"Picor, descamación y sensaciones. Si la descamación viene con placas, enrojecimiento o dolor, el asistente corta hacia bandera roja.","tipo":"opcion","opciones":[{"valor":"normal","etiqueta":"Normal"},{"valor":"graso","etiqueta":"Graso"},{"valor":"seco","etiqueta":"Seco"},{"valor":"sensible","etiqueta":"Sensible"},{"valor":"dermatitis_leve","etiqueta":"Dermatitis leve / caspa"},{"valor":"dermatitis_severa","etiqueta":"Dermatitis severa","banderaMedica":true},{"valor":"psoriasis_sospecha","etiqueta":"Sospecha de psoriasis","banderaMedica":true},{"valor":"lesiones_abiertas","etiqueta":"Lesiones abiertas","banderaMedica":true}],"opcional":true},{"clave":"nivelFrizz","etiqueta":"Nivel de frizz / estática","ayuda":"En 1C suele ser señal de cutícula abierta y estática.","tipo":"opcion","opciones":[{"valor":"bajo","etiqueta":"Bajo"},{"valor":"medio","etiqueta":"Medio"},{"valor":"alto","etiqueta":"Alto"}],"opcional":true},{"clave":"procesosQuimicos","etiqueta":"Procesos químicos previos (con fechas en observaciones)","tipo":"multi","opciones":[{"valor":"ninguno","etiqueta":"Ninguno"},{"valor":"tinte","etiqueta":"Tinte / coloración"},{"valor":"decoloracion","etiqueta":"Decoloración / mechas"},{"valor":"alisado","etiqueta":"Alisado permanente / keratina"},{"valor":"permanente","etiqueta":"Permanente (rizado químico)"},{"valor":"henna","etiqueta":"Henna / tintes vegetales"}],"opcional":true},{"clave":"frecuenciaTinte","etiqueta":"Frecuencia de coloración","tipo":"opcion","opciones":[{"valor":"sin_tinte","etiqueta":"No se tiñe"},{"valor":"cada_3_6_semanas","etiqueta":"Cada 3–6 semanas (cobertura)"},{"valor":"cada_8_semanas_o_menos","etiqueta":"Cada 8 semanas o menos"},{"valor":"esporadico","etiqueta":"Esporádico (más de 8 semanas)"}],"opcional":true},{"clave":"objetivoPrincipal","etiqueta":"Objetivo principal","ayuda":"Una sola opción dominante: ordena el plan cuando varias reglas aplican.","tipo":"opcion","opciones":[{"valor":"volumen","etiqueta":"Volumen"},{"valor":"control_frizz","etiqueta":"Control de frizz / estática"},{"valor":"brillo","etiqueta":"Brillo"},{"valor":"reparacion","etiqueta":"Reparación"},{"valor":"mantenimiento","etiqueta":"Mantenimiento"}]},{"clave":"densidadPorZonas","etiqueta":"Densidad por zonas","tipo":"multi","opciones":[{"valor":"uniforme","etiqueta":"Uniforme"},{"valor":"entradas","etiqueta":"Entradas despobladas"},{"valor":"coronilla","etiqueta":"Coronilla rala"},{"valor":"laterales","etiqueta":"Laterales débiles"}],"opcional":true}]}'::jsonb, 'borrador'),
  ('flujo.ondulado', 'es', ARRAY['2A', '2B', '2C']::text[], '{"titulo":"Preguntas para cabello ondulado","descripcion":"En tipo 2 entran la detección de build-up y de transición post-química, además del frizz y la definición actual de la onda.","preguntas":[{"clave":"nivelFrizz","etiqueta":"Nivel de frizz","ayuda":"En tipo 2 suele ser síntoma de deshidratación.","tipo":"opcion","opciones":[{"valor":"bajo","etiqueta":"Bajo"},{"valor":"medio","etiqueta":"Medio"},{"valor":"alto","etiqueta":"Alto"}]},{"clave":"definicionOnda","etiqueta":"¿Qué tan definida luce la onda hoy?","tipo":"opcion","opciones":[{"valor":"definida","etiqueta":"Definida"},{"valor":"se_aplasta","etiqueta":"Se aplasta a las pocas horas"},{"valor":"sin_forma","etiqueta":"Sin forma / apagada"}],"opcional":true},{"clave":"acumulacionProducto","etiqueta":"¿Usa habitualmente siliconas insolubles, ceras o aceites minerales?","ayuda":"Detecta el build-up: activa el detox antes que cualquier regla de definición.","tipo":"opcion","opciones":[{"valor":"si","etiqueta":"Sí"},{"valor":"no","etiqueta":"No"}],"opcional":true},{"clave":"grasaRaiz","etiqueta":"¿Qué tan rápido se engrasa la raíz?","tipo":"opcion","opciones":[{"valor":"mismo_dia","etiqueta":"El mismo día del lavado"},{"valor":"1_2_dias","etiqueta":"A los 1-2 días"},{"valor":"3_mas_dias","etiqueta":"A los 3 días o más"}],"opcional":true},{"clave":"tipoCueroCabelludo","etiqueta":"Tipo de cuero cabelludo","tipo":"opcion","opciones":[{"valor":"normal","etiqueta":"Normal"},{"valor":"graso","etiqueta":"Graso"},{"valor":"seco","etiqueta":"Seco"},{"valor":"sensible","etiqueta":"Sensible"},{"valor":"dermatitis_leve","etiqueta":"Dermatitis leve / caspa"},{"valor":"dermatitis_severa","etiqueta":"Dermatitis severa","banderaMedica":true},{"valor":"psoriasis_sospecha","etiqueta":"Sospecha de psoriasis","banderaMedica":true},{"valor":"lesiones_abiertas","etiqueta":"Lesiones abiertas","banderaMedica":true}],"opcional":true},{"clave":"procesosQuimicos","etiqueta":"Procesos químicos previos (clave para detectar transición: dos texturas visibles)","tipo":"multi","opciones":[{"valor":"ninguno","etiqueta":"Ninguno"},{"valor":"tinte","etiqueta":"Tinte / coloración"},{"valor":"decoloracion","etiqueta":"Decoloración / mechas"},{"valor":"alisado","etiqueta":"Alisado permanente / keratina"},{"valor":"permanente","etiqueta":"Permanente (rizado químico)"},{"valor":"henna","etiqueta":"Henna / tintes vegetales"}],"opcional":true},{"clave":"frecuenciaTinte","etiqueta":"Frecuencia de coloración","tipo":"opcion","opciones":[{"valor":"sin_tinte","etiqueta":"No se tiñe"},{"valor":"cada_3_6_semanas","etiqueta":"Cada 3–6 semanas (cobertura)"},{"valor":"cada_8_semanas_o_menos","etiqueta":"Cada 8 semanas o menos"},{"valor":"esporadico","etiqueta":"Esporádico (más de 8 semanas)"}],"opcional":true},{"clave":"objetivoPrincipal","etiqueta":"Objetivo principal","tipo":"opcion","opciones":[{"valor":"definicion","etiqueta":"Definición máxima"},{"valor":"mas_rizo","etiqueta":"Maximizar definición hacia rizo"},{"valor":"reparacion","etiqueta":"Reparación"},{"valor":"control_frizz","etiqueta":"Control de frizz"},{"valor":"mantenimiento","etiqueta":"Onda suelta y natural / mantenimiento"}]},{"clave":"densidadPorZonas","etiqueta":"Densidad por zonas","tipo":"multi","opciones":[{"valor":"uniforme","etiqueta":"Uniforme"},{"valor":"entradas","etiqueta":"Entradas despobladas"},{"valor":"coronilla","etiqueta":"Coronilla rala"},{"valor":"laterales","etiqueta":"Laterales débiles"}],"opcional":true}]}'::jsonb, 'borrador'),
  ('flujo.canas', 'es', NULL, '{"titulo":"Módulo de canas","descripcion":"Mini-módulo transversal (Entrega 2): no es un flujo aparte, es una rama que se suma al flujo del tipo base. Si no hay canas, marca \"Sin canas\" y continúa.","preguntas":[{"clave":"estadoCanas","etiqueta":"Porcentaje de canas","ayuda":"Estimación visual con guía fotográfica.","tipo":"opcion","opciones":[{"valor":"sin_canas","etiqueta":"Sin canas"},{"valor":"menos_25","etiqueta":"Menos del 25%"},{"valor":"entre_25_50","etiqueta":"Entre 25% y 50%"},{"valor":"mas_50","etiqueta":"Más del 50%"}]},{"clave":"distribucionCanas","etiqueta":"Distribución","ayuda":"Las canas del marco del rostro priorizan técnica localizada.","tipo":"opcion","opciones":[{"valor":"sienes","etiqueta":"Sienes"},{"valor":"corona","etiqueta":"Corona"},{"valor":"marco_rostro","etiqueta":"Marco del rostro"},{"valor":"difusa","etiqueta":"Difusa"}],"opcional":true},{"clave":"amarillamientoCanas","etiqueta":"¿Las canas muestran tonos amarillos o apagados?","tipo":"booleano","opcional":true},{"clave":"texturaCana","etiqueta":"Textura de la cana","tipo":"opcion","opciones":[{"valor":"igual","etiqueta":"Igual al resto"},{"valor":"mas_gruesa_aspera","etiqueta":"Más gruesa / áspera"},{"valor":"patron_distinto","etiqueta":"Patrón distinto"}],"opcional":true},{"clave":"aparicionCanas","etiqueta":"Aparición de las canas","tipo":"opcion","opciones":[{"valor":"gradual","etiqueta":"Gradual, con los años"},{"valor":"subita_temprana","etiqueta":"Abundante y rápida antes de los ~25 años"}],"opcional":true},{"clave":"situacionColor","etiqueta":"Situación de color","tipo":"opcion","opciones":[{"valor":"natural","etiqueta":"Natural"},{"valor":"tenida_cobertura","etiqueta":"Teñida (cobertura)"},{"valor":"en_transicion","etiqueta":"En transición"},{"valor":"quiere_transicion","etiqueta":"Quiere iniciar transición"}],"opcional":true},{"clave":"objetivoCana","etiqueta":"Objetivo con la cana","ayuda":"Decisión de la clienta, nunca del sistema: presentar opciones sin empujar.","tipo":"opcion","opciones":[{"valor":"lucirla","etiqueta":"Lucirla"},{"valor":"matizarla","etiqueta":"Matizarla"},{"valor":"cubrirla","etiqueta":"Cubrirla"},{"valor":"transicionar","etiqueta":"Transicionar"}],"opcional":true}]}'::jsonb, 'borrador'),
  ('flujo.cabina', 'es', NULL, '{"titulo":"Reconocimiento en cabina — caída y cuero cabelludo","descripcion":"Guía de la Entrega 2: la primera pregunta siempre es ¿rotura o caída? Las señales médicas convierten el plan en derivación a dermatólogo.","preguntas":[{"clave":"senalesCaida","etiqueta":"Señales de caída o pérdida","ayuda":"Rotura: hebras partidas sin bulbo (cosmético). Caída: la hebra sale completa con bulbo blanquecino. Hasta 50–100 hebras al día es normal.","tipo":"multi","opciones":[{"valor":"sin_senales","etiqueta":"Sin señales"},{"valor":"caida_normal","etiqueta":"Caída dentro de lo normal"},{"valor":"rotura_sin_bulbo","etiqueta":"Rotura sin bulbo (puntitas \"paradas\")"},{"valor":"traccion_sienes","etiqueta":"Raleo en sienes con tensión crónica"},{"valor":"parches_redondos","etiqueta":"Parches redondos bien definidos","banderaMedica":true},{"valor":"caida_difusa_subita","etiqueta":"Caída difusa y súbita (1–3 meses)","banderaMedica":true},{"valor":"raya_ensancha","etiqueta":"Raya que se ensancha / coronilla fina","banderaMedica":true},{"valor":"zonas_lisas_brillantes","etiqueta":"Zonas lisas y brillantes sin vello","banderaMedica":true},{"valor":"cuero_inflamado_pustulas","etiqueta":"Inflamación, pústulas o dolor","banderaMedica":true}],"opcional":true},{"clave":"situacionCaida","etiqueta":"Situación frente a la caída","ayuda":"Activa el acompañamiento A-01 a A-05 para clientas derivadas o en manejo médico.","tipo":"opcion","opciones":[{"valor":"sin_caida","etiqueta":"Sin caída relevante"},{"valor":"en_evaluacion_medica","etiqueta":"Derivada / en evaluación médica"},{"valor":"diagnostico_confirmado_manejo","etiqueta":"En tratamiento dermatológico"},{"valor":"posparto_ventana","etiqueta":"Posparto (ventana esperada)"},{"valor":"perdida_estable_camuflaje","etiqueta":"Pérdida estable: quiere verse mejor hoy"}],"opcional":true},{"clave":"descamacion","etiqueta":"Descamación del cuero cabelludo","tipo":"opcion","opciones":[{"valor":"sin_descamacion","etiqueta":"Sin descamación"},{"valor":"fina_blanca","etiqueta":"Fina y blanca, sin enrojecimiento"},{"valor":"placas_enrojecimiento","etiqueta":"Placas, enrojecimiento, exudado o dolor","banderaMedica":true}],"opcional":true}]}'::jsonb, 'borrador'),
  ('flujo.tipos34', 'es', ARRAY['3A', '3B', '3C', '4A', '4B', '4C']::text[], '{"titulo":"Dimensiones reforzadas — tipos 3 y 4","descripcion":"Complemento de la Entrega 4: encogimiento como dato, objetivo de estilo y peinados protectores. El motor de rizos existente sigue siendo la fuente de verdad.","preguntas":[{"clave":"objetivoEstilo","etiqueta":"Objetivo de estilo","tipo":"opcion","opciones":[{"valor":"definido_natural","etiqueta":"Definido al natural"},{"valor":"estirado_sin_calor","etiqueta":"Estirado sin calor"},{"valor":"protector","etiqueta":"Peinado protector"}],"opcional":true},{"clave":"protectorEnUso","etiqueta":"Peinado protector en uso","tipo":"opcion","opciones":[{"valor":"ninguno","etiqueta":"Ninguno"},{"valor":"trenzas","etiqueta":"Trenzas"},{"valor":"twists","etiqueta":"Twists"},{"valor":"extensiones","etiqueta":"Extensiones"}],"opcional":true},{"clave":"senalesProtector","etiqueta":"Señales bajo el protector","ayuda":"El dolor nunca es el precio de un peinado.","tipo":"multi","opciones":[{"valor":"sin_molestias","etiqueta":"Sin molestias"},{"valor":"dolor_tension_bultitos","etiqueta":"Dolor, tirantez o \"bultitos\""},{"valor":"picor_mal_olor","etiqueta":"Picor intenso o mal olor persistente"},{"valor":"pustulas_lesiones","etiqueta":"Pústulas o lesiones en la piel","banderaMedica":true}],"opcional":true},{"clave":"largoNaturalCm","etiqueta":"Largo natural (cm, en encogimiento)","ayuda":"T4-01: el encogimiento es dato, no defecto. Registrar ambos largos.","tipo":"texto","opcional":true},{"clave":"largoEstiradoCm","etiqueta":"Largo estirado (cm, tracción suave en húmedo)","ayuda":"Mismo mechón de referencia (nuca o coronilla) para comparabilidad.","tipo":"texto","opcional":true},{"clave":"manipulacion","etiqueta":"Frecuencia de desenredado y peinado","tipo":"opcion","opciones":[{"valor":"diaria","etiqueta":"Diaria"},{"valor":"varias_semana","etiqueta":"Varias veces por semana"},{"valor":"semanal_o_menos","etiqueta":"Semanal o menos"}],"opcional":true}]}'::jsonb, 'borrador')
